package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * A station key ("outstation1:" and base64url JSON {relay, channel, key}, as the outstation and a friend's invite
 * give it; "portal1:" from before the name was outstation): where the plugin sends the game, and with what key.
 */
public final class Attach
{
	/** The Outside relay's host: the only one the Plugin Hub's version talks to (11/16/2026, the reviewer on
	 *  runelite/plugin-hub#20811: "Hub plugins aren't allowed to take a URL from a server response then connect to it…
	 *  make sure the hostname portion of relay is relay.ghillie.workers.dev"). */
	public static final String HOME_HOST = "relay.ghillie.workers.dev";
	/** Its address, the base of every request the Hub's version makes. */
	public static final String HOME = "https://" + HOME_HOST;

	private final String relay;
	private final String channel;
	private final String key;

	public Attach(String relay, String channel, String key)
	{
		this.relay = relay;
		this.channel = channel;
		this.key = key;
	}

	public String getRelay()
	{
		return relay;
	}

	public String getChannel()
	{
		return channel;
	}

	public String getKey()
	{
		return key;
	}

	/** The key read (with RuneLite's own Gson), or null when it isn't one. */
	public static Attach parse(String code, Gson gson)
	{
		if (code == null)
		{
			return null;
		}
		String c = code.trim();
		int colon = c.indexOf(':');
		if (colon < 0)
		{
			return null;
		}
		String prefix = c.substring(0, colon);
		if (!prefix.equals("outstation1") && !prefix.equals("portal1"))
		{
			return null;
		}
		try
		{
			String json = new String(Base64.getUrlDecoder().decode(c.substring(colon + 1)), StandardCharsets.UTF_8);
			JsonObject o = gson.fromJson(json, JsonObject.class);
			String relay = o.get("relay").getAsString();
			String channel = o.get("channel").getAsString();
			String key = o.get("key").getAsString();
			if (relay.isEmpty() || channel.isEmpty() || key.length() < 8)
			{
				return null;
			}
			// (the Hub's version: a key for any other relay is no key, whether pasted or from /claim's answer, and
			// every request is built on HOME, never on what the key says; the whole plugin, in developer mode, also
			// takes an outstation's own relay or a local one)
			if (!isHome(relay))
			{
				return null;
			}
			return new Attach(HOME, channel, key);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Whether a key's relay is the Outside relay itself: relay.ghillie.workers.dev, as https://, wss:// or bare, with no
	 *  port, path or anything else. */
	public static boolean isHome(String relay)
	{
		if (relay == null)
		{
			return false;
		}
		String r = relay.trim().replaceAll("/+$", "");
		if (r.startsWith("https://"))
		{
			r = r.substring(8);
		}
		else if (r.startsWith("wss://"))
		{
			r = r.substring(6);
		}
		return r.equalsIgnoreCase(HOME_HOST);
	}

	/** The snapshot's address (11/16/2026; docs/protocol.md, "The snapshot"): POST http(s)://…/game/<channel>?key=…&v=…. */
	public String postUrl(String version)
	{
		// (&proof=1, 11/17/2026: the answer says what the page's proof did, while it's still to be made)
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/game/" + enc(channel) + "?") + "&v=" + enc(version) + "&proof=1";
	}

	/** The relay's keep for the page (11/14/2026): http(s)://…/keep/<channel>/<what>?key=… (a bare relay as https://). */
	public String keepUrl(String what)
	{
		String base = relay.trim().replaceAll("/+$", "");
		if (base.startsWith("wss://"))
		{
			base = "https://" + base.substring(6);
		}
		else if (base.startsWith("ws://"))
		{
			base = "http://" + base.substring(5);
		}
		else if (!base.contains("://"))
		{
			base = "https://" + base;
		}
		return base + "/keep/" + enc(channel) + "/" + enc(what) + "?key=" + enc(key);
	}

	/** The page's address for the Dink plugin's webhooks (11/16/2026, "Copy my address for Dink"): http(s)://…/dink/<channel>?key=…,
	 *  on the relay every request goes to. Only copied for the player to paste into Dink; never fetched here. */
	public String dinkAddress()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/dink/" + enc(channel) + "?");
	}

	/** Who stands behind the page (11/15/2026): http(s)://…/proof/<channel>, anyone's. */
	public String proofUrl()
	{
		return keepUrl("x").replaceFirst("/keep/.*$", "/proof/" + enc(channel));
	}

	/** Friends only, set from the plugin (11/16/2026, the permissions review): http(s)://…/code/<channel>?key=…. */
	public String codeUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/code/" + enc(channel) + "?");
	}

	/** The page taken down by its own key (11/16/2026): http(s)://…/channels/<channel>?key=…. */
	public String takeDownUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/channels/" + enc(channel) + "?");
	}

	/** A token to tend the page's chat from the page, handed in by its own key (11/16/2026): http(s)://…/tend/<channel>?key=…. */
	public String tendUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/tend/" + enc(channel) + "?");
	}

	/** A token to edit the page from the page (its arrangement and its theme song), handed in by its own key (11/21/2026,
	 *  update 6): http(s)://…/edit/<channel>?key=…. */
	public String editUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/edit/" + enc(channel) + "?");
	}

	/** The page, opened to arrange it and set its theme song: the token in the fragment, which no server sees, and the
	 *  watch code when it's friends only (11/21/2026). */
	public String editPage(String code, String token)
	{
		return page(code) + "#edit=" + token;
	}

	/** The page, opened to tend its chat: the token in the fragment, which no server sees (11/16/2026). */
	public String tendPage(String token)
	{
		return page() + "#tend=" + token;
	}

	/** The page's kept game, as anyone reads it (403 when it's friends only and no code is given). */
	public String gameReadUrl()
	{
		return keepUrl("x").replaceFirst("/keep/.*$", "/game/" + enc(channel));
	}

	/** The page with its key in the fragment, for the aether under the page's own name (11/18/2026): no server sees a
	 *  fragment, and the page takes it out of the address at once. */
	public String aetherPage(String code)
	{
		return page(code) + "#aether=" + enc(key);
	}

	/** The page with a watch code, for friends (11/16/2026). */
	public String page(String code)
	{
		return code == null || code.isEmpty() ? page() : page() + "?code=" + enc(code);
	}

	/** The page's recorded encounters (11/21/2026; docs/protocol.md, "Recorded fights"): http(s)://…/fights/<channel>?key=…,
	 *  the list as its owner reads it (GET) and one put up (POST, multipart). */
	public String fightsUrl()
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/fights/" + enc(channel) + "?");
	}

	/** One of them shown to anyone or kept to themselves (POST): http(s)://…/fights/<channel>/<id>?key=…&public=1|0. */
	public String fightUrl(String id, boolean shown)
	{
		return keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/fights/" + enc(channel) + "/" + enc(id) + "?") + "&public=" + (shown ? "1" : "0");
	}

	/** One of them changed (POST, 11/21/2026): http(s)://…/fights/<channel>/<id>?key=…&<what> (kept=1|0, featured=1|0);
	 *  with no what, the fight itself (DELETE: taken down). */
	public String fightUrl(String id, String what)
	{
		String u = keepUrl("x").replaceFirst("/keep/[^?]*\\?", "/fights/" + enc(channel) + "/" + enc(id) + "?");
		return what == null || what.isEmpty() ? u : u + "&" + what;
	}

	/** Its page on Outside: outside.wiki/<name>/fight/<id>, with a friends-only page's watch code. */
	public String fightPage(String id, String code)
	{
		String p = page() + "/fight/" + enc(id);
		return code == null || code.isEmpty() ? p : p + "?code=" + enc(code);
	}

	/** The outstation's page on Outside. */
	public String page()
	{
		// (11/16/2026: outside.wiki/<name>, as Open my page opens it; it was ghillie.wiki/outside?player=)
		return "https://outside.wiki/" + enc(channel);
	}

	private static String enc(String s)
	{
		return URLEncoder.encode(s, StandardCharsets.UTF_8).replace("+", "%20");
	}
}

package wiki.outside;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Kill counts and clue counts as the game's chat says them (11/16/2026, Jace: field reports for Hub players without
 * Dink): "Your Vorkath kill count is: 418", "You have completed 152 hard Treasure Trails." Kept per account on this
 * RuneLite's profile and sent with each update (OutsidePlugin.read, "kc"); the relay reports a count that's gone up.
 * The patterns are Dink's (github.com/pajlads/DinkPlugin: KillCountNotifier, ClueNotifier; BSD 2-Clause, Copyright (c)
 * 2022, pajlads), as the whole plugin's Reports reads them. Kept apart from RuneLite so it's tested.
 */
final class Counts
{
	private static final Pattern KILL = Pattern.compile("^Your (?:completed )?(.+?) (?:(?:kill|chest|completion|harvest|success) )?count is: ?(?:@[A-Za-z0-9_]+@)?([\\d,]+)\\b.*$");
	private static final Pattern CLUE = Pattern.compile("^You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?\\s*$",
		Pattern.CASE_INSENSITIVE);
	/** at most this many bosses kept (the game has fewer) */
	static final int MOST = 250;
	/** the most a count can say */
	static final int TOP = 10_000_000;
	/** never kept or sent: a Wilderness boss's count says where they've been (the relay's WILDERNESS_BOSSES, the same) */
	private static final String[] WILDERNESS = {"artio", "callisto", "calvar'ion", "chaos elemental", "chaos fanatic",
		"crazy archaeologist", "scorpia", "spindel", "venenatis", "vet'ion", "king black dragon", "revenant"};

	private final Map<String, Integer> kills = new TreeMap<>();
	private final Map<String, Integer> clues = new TreeMap<>();

	/** A game message read: true when it changed a count. */
	synchronized boolean take(String line)
	{
		if (line == null)
		{
			return false;
		}
		String m = line.trim();
		Matcher k = KILL.matcher(m);
		if (k.matches())
		{
			String boss = k.group(1).trim();
			return !wilderness(boss) && put(kills, boss, number(k.group(2)));
		}
		Matcher c = CLUE.matcher(m);
		if (c.matches())
		{
			return put(clues, c.group(2).toLowerCase(Locale.ROOT), number(c.group(1)));
		}
		return false;
	}

	static boolean wilderness(String boss)
	{
		String b = boss.toLowerCase(Locale.ROOT);
		for (String w : WILDERNESS)
		{
			if (b.startsWith(w))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean put(Map<String, Integer> to, String name, int n)
	{
		if (name.isEmpty() || name.length() > 60 || n < 0 || n > TOP || (!to.containsKey(name) && to.size() >= MOST))
		{
			return false;
		}
		Integer was = to.put(name, n);
		return was == null || was != n;
	}

	private static int number(String s)
	{
		try
		{
			return Integer.parseInt(s.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** {"kills": {boss: n}, "clues": {tier: n}}, or null with none. */
	synchronized JsonObject json()
	{
		if (kills.isEmpty() && clues.isEmpty())
		{
			return null;
		}
		JsonObject o = new JsonObject(), k = new JsonObject(), c = new JsonObject();
		kills.forEach(k::addProperty);
		clues.forEach(c::addProperty);
		o.add("kills", k);
		o.add("clues", c);
		return o;
	}

	/** The counts as kept (json()'s shape); anything else leaves them empty. */
	synchronized void load(JsonObject o)
	{
		kills.clear();
		clues.clear();
		if (o == null)
		{
			return;
		}
		for (String part : new String[]{"kills", "clues"})
		{
			if (!o.has(part) || !o.get(part).isJsonObject())
			{
				continue;
			}
			for (Map.Entry<String, JsonElement> e : o.getAsJsonObject(part).entrySet())
			{
				try
				{
					if (!part.equals("kills") || !wilderness(e.getKey()))
					{
						put(part.equals("kills") ? kills : clues, e.getKey(), e.getValue().getAsInt());
					}
				}
				catch (RuntimeException ignored)
				{
				}
			}
		}
	}
}

package wiki.outside;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Every boss, raid and boss-type minigame the game has, and how the encounter recorder starts and ends a recording of
 * each (11/22/2026; plugin/docs/encounter-bosses.md is this table written up, with what was wrong and its sources).
 * Read by Encounters for its decisions (where a recording starts on entering, which NPCs are a place's boss, which count
 * lines end it and which pass by, whose death ends it with no count line, how long a fight may go quiet), and by
 * EncounterBossesTest, which walks every row through those decisions against its own list of what each should do.
 *
 * <p>Where each fact comes from (nothing from memory):
 * <ul>
 * <li>the areas and their regions: RuneLite's DiscordGameEventType (runelite/runelite master, 11/18/2026), as
 * Presence.AREAS holds them; a boss Discord has no area for is placed by its boss's fight instead (its regions here
 * are the OSRS Wiki's map pins, LocLine's x and y, for the write-up only: nothing reads them);</li>
 * <li>the NPC names: the game's cache (OpenRS2's cache 2772, revision 242, 11/18/2026; its NPC configs read with
 * ghillie's replay/3d defs.js), each name exactly as the cache spells it (case is ignored when matching);</li>
 * <li>the count lines: RuneLite's ChatCommandsPlugin (its KILLCOUNT_PATTERN, its boss-name table, and its tests'
 * lines, ChatCommandsPluginTest) and Dink's KillCountNotifier and its tests (pajlads/DinkPlugin, 11/22/2026), quoted in
 * each row; where neither quotes the game's line, the row says so and ends on any count line;</li>
 * <li>how a fight goes (an instance or not, several bosses, a phase that "dies"): the OSRS Wiki's pages, cited in the
 * rows.</li>
 * </ul>
 */
final class EncounterBosses
{
	/** How a recording of it starts. */
	enum Start
	{
		/** on entering its area (a raid, the Inferno, the Fight Cave) */
		ENTRY,
		/** its area: an instance on entering; its open (public) copy with the fight with its boss (11/22/2026, the Mole) */
		PLACE,
		/** with the fight with its boss: a hitsplat either way, or the player attacking it (an open area like Barrows,
		 *  or a boss Discord has no area for, anywhere) */
		FIGHT,
		/** by its own rule elsewhere: a run's way in (Encounters.Run), Doom of Mokhaiotl's forms (DOOM_IDS) */
		OWN,
		/** never by itself: skilling (Wintertodt, Tempoross), a lobby, a raid's part, the Wilderness */
		NEVER
	}

	/** How a recording of it ends (besides the player's death, leaving and logging out). */
	enum End
	{
		/** one kill: its count line ("killed"), or its boss's death with no line */
		KILL,
		/** several bosses: a count line ends it once none of the others fought is still up ("killed") */
		LAST,
		/** waves: only the last boss's count line ends it ("completed"), never a wave's */
		WAVES,
		/** a chest: only the chest's count line or its loot ends it ("looted"), never a boss's kill */
		CHEST,
		/** a run (the Gauntlets, the Colosseum): Encounters.runEnding */
		RUN,
		/** a raid: from entering to leaving its treasure room (Encounters' raid rules) */
		RAID,
		/** a delve of Doom of Mokhaiotl: to the death, or the claim and leaving */
		DELVE,
		/** never recorded by itself */
		NONE
	}

	/** One row. */
	static final class Boss
	{
		/** its own name (the hiscores' or the wiki's), and the area's when Discord names one */
		final String name;
		/** "boss", "raid", "minigame", "wilderness", "skilling" */
		final String kind;
		/** Discord's area for it, or null: a place of its own, named for it */
		final String area;
		/** the regions: Discord's (Presence's) for an area, the wiki's map pins for one Discord misses (the write-up's) */
		final int[] regions;
		final Start start;
		final End end;
		/** its boss's names (lower case): a fight with one starts it where it starts by the fight */
		final Set<String> npcs;
		/** the names whose death ends it with no count line (lower case; empty: never, the line always comes) */
		final Set<String> deaths;
		/** NPC ids whose death is only a phase (the Kalphite Queen's first form) */
		final Set<Integer> phases;
		/** the count lines' names (as counted() gives them) that end it; null: any count line */
		final Set<String> ends;
		/** ticks with no hitsplat on or from the player before it ends ("the fight stopped"), where it started by the
		 *  fight; 0: never */
		final int idle;
		/** a place of its own: ticks with none of its NPCs in sight before it's left; 0: never */
		final int gone;
		/** ticks out of its area (in no named area) before it's left */
		final int grace;
		/** the count line as the game words it, with where that wording comes from */
		final String line;
		/** a place of its own (area null): the recording's area, named for it; else null */
		final Presence.Area place;

		private Boss(Row r)
		{
			name = r.name;
			kind = r.kind;
			area = r.area;
			regions = r.regions;
			start = r.start;
			end = r.end;
			npcs = lower(r.npcs);
			deaths = r.deaths == null ? npcs : lower(r.deaths);
			phases = Collections.unmodifiableSet(new HashSet<>(r.phases));
			ends = r.ends == null ? null : lower(r.ends);
			idle = r.idle;
			gone = r.gone;
			grace = r.grace;
			line = r.line;
			place = r.area == null && (r.start == Start.FIGHT) ? new Presence.Area(r.name, Presence.BOSS, r.regions) : null;
		}

		/** Whether it starts the tick they're in its area (an instance, as RuneLite's top-level world view says). */
		boolean startsOnEntry(boolean instance)
		{
			return start == Start.ENTRY || start == Start.PLACE && instance;
		}

		/** Whether it starts with the fight with its boss, not on entering. */
		boolean startsByFight(boolean instance)
		{
			return start == Start.FIGHT || start == Start.PLACE && !instance;
		}

		/** Whether an NPC of this name is its boss (any case; a non-breaking space as the game sends it). */
		boolean isBoss(String npc)
		{
			return npc != null && npcs.contains(norm(npc));
		}

		/** Whether an NPC of this name is one whose death ends it with no count line. */
		boolean isDeath(String npc)
		{
			return npc != null && deaths.contains(norm(npc));
		}

		/** Whether this NPC's death (its id and name) ends it with no count line: one of its deaths, not a phase. */
		boolean diesTo(int id, String npc)
		{
			return isDeath(npc) && !phases.contains(id);
		}

		/** Whether a count line naming {@code counted} (as counted() gives it) is one that ends it. */
		boolean endsOn(String counted)
		{
			return ends == null || counted != null && ends.contains(norm(counted));
		}

		/** A count line naming {@code counted}: why it ends the recording, or null for one that passes by (a wave's, a
		 *  sub-boss's, a moon's before the chest; one of several bosses with another fought still up: {@code otherUp}).
		 *  A raid's, a run's and a delve's count lines are their own rules' (null here). */
		String killEnds(String counted, boolean otherUp)
		{
			switch (end)
			{
				case KILL:
				case NONE:
					return endsOn(counted) ? "killed" : null;
				case LAST:
					return endsOn(counted) && !otherUp ? "killed" : null;
				case WAVES:
					return endsOn(counted) ? "completed" : null;
				case CHEST:
					return endsOn(counted) ? "looted" : null;
				default:
					return null;
			}
		}

		/** Whether a fight that's gone quiet ends it: {@code idle} ticks since the last hitsplat on or from the player,
		 *  where it started by the fight (an open area, or a place of its own; never an instance entered). */
		boolean idleEnds(boolean instance, int now, int lastFight)
		{
			return idle > 0 && (area == null || startsByFight(instance)) && now >= lastFight + idle;
		}

		/** A place of its own: whether it's left, none of its NPCs seen since {@code seenAt}. */
		boolean goneEnds(int now, int seenAt)
		{
			return area == null && gone > 0 && now >= seenAt + gone;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	/** A row as it's written below. */
	private static final class Row
	{
		final String name, kind;
		String area;
		int[] regions = new int[0];
		Start start = Start.PLACE;
		End end = End.KILL;
		List<String> npcs = new ArrayList<>(), deaths, ends;
		List<Integer> phases = new ArrayList<>();
		int idle = Encounters.OPEN_IDLE, gone, grace = Encounters.LEFT_BOSS;
		String line;

		Row(String name, String kind)
		{
			this.name = name;
			this.kind = kind;
		}

		/** Discord's area of this name (its regions read from Presence: a test checks each is there) */
		Row area(String a)
		{
			area = a;
			Presence.Area p = discord(a);
			regions = p == null ? new int[0] : p.regions;
			return this;
		}

		Row regions(int... r)
		{
			regions = r;
			return this;
		}

		Row start(Start s)
		{
			start = s;
			return this;
		}

		Row end(End e)
		{
			end = e;
			return this;
		}

		Row npcs(String... n)
		{
			npcs.addAll(Arrays.asList(n));
			return this;
		}

		Row deaths(String... n)
		{
			deaths = Arrays.asList(n);
			return this;
		}

		Row phases(Integer... ids)
		{
			phases.addAll(Arrays.asList(ids));
			return this;
		}

		Row ends(String... n)
		{
			ends = Arrays.asList(n);
			return this;
		}

