	/** the Gauntlet's lobby, where the player is sent after the Hunllef dies (or they die) and its chest stands */
	static final int GAUNTLET_LOBBY = 12127;
	/** a click on the way in counts for this many ticks: the map loading after it is the run's start */
	static final int RUN_ARMED = 50;
	/** ticks out of the run's instance (no kill, nothing claimed) before it counts as left: the teleport platform, the
	 *  barrier's Escape, an escape crystal, the Colosseum's way out */
	static final int RUN_LEFT = 5;
	/** the Hunllef killed: the most it waits for the chest (5 minutes) */
	static final int RUN_CHEST_WAIT = 500;
	/** a fight ended by its chest (Barrows' brothers, then their chest; the Moons of Peril twice this): ticks with no
	 *  hitsplat on or from the player before it's given up, for the tunnels and the walks between (11/22/2026) */
	static final int RUN_IDLE = 500;

	/** the game's kill and completion count lines ("Your Vorkath kill count is: 418.", "Your completed Chambers of Xeric
	 *  count is: 12."), as Counts reads them; the count may open with one of the game's colour macros, "@mes_hl_red@",
	 *  which Text.removeTags leaves (11/21/2026, round six: RuneLite 1.13.7's chat commands and Dink allow it; DropTracker
	 *  dates it to the game's 08/26/2026 update) */
	static final Pattern KILL_LINE = Pattern.compile("^Your (?:completed )?(.+?) (?:(?:kill|chest|completion|harvest|success) )?count is: ?(?:@[A-Za-z0-9_]+@)?([\\d,]+)\\b.*$");
	/** TzHaar-Ket-Rak's challenges' count line, which KILL_LINE's form doesn't take ("Your completion count for
	 *  TzHaar-Ket-Rak's First Challenge is: 1.", RuneLite's ChatCommandsPluginTest; its KILLCOUNT_PATTERN's "completion
	 *  count for "): its groups as KILL_LINE's (11/22/2026) */
	static final Pattern CHALLENGE_LINE = Pattern.compile("^Your completion count for (.+?) is: ?(?:@[A-Za-z0-9_]+@)?([\\d,]+)\\b.*$");
	/** the count lines that are no fight's: an agility course's laps, the Agility Arena's tickets, the herbiboar's
	 *  harvests (KILL_LINE takes them; RuneLite's chat commands and Dink tell them by these words; 11/22/2026) */
	static final Pattern NOT_A_KILL = Pattern.compile("^Your .+ (?:lap|Total Ticket|harvest) count is\\b.*$");
	/** the raids' friends-chat lines kept: a completion or a time (everything else there can be about other players) */
	static final Pattern COMPLETION = Pattern.compile("(?i)raid is complete|team size|duration|personal best|completion time|challenge complete|congratulations");

	/** what the recorder needs from the plugin */
	interface Host
	{
		/** the plugin's own folder for its files (Plugin.getPluginDirectory) */
		Filepath folder() throws IOException;

		/** whether the character logged in has an Outside page (recording needs one) */
		boolean hasPage();

		/** "Record my encounters" */
		boolean autoOn();

		/** "Players around you" */
		boolean otherPlayers();

		/** the NPC ids listed to start one */
		String npcIds();

		/** the folder's size cap, in bytes */
		long most();

		/** the plugin's version, for the header */
		String version();

		/** a recording's started, is running (its words) or stopped: the side tab's line (null: none running) */
		void recording(String words, boolean running);

		/** a recording's packed (its file name), or files changed: the side tab's list read again */
		void filesChanged(String packed);

		/** a ground item's name, colour and value as RuneLite's Ground Items plugin shows them ({text, "#rrggbb", value as a
		 *  Long}), or null; on the client's thread (11/21/2026, the scene moment's labels) */
		Object[] itemLabel(int id, int qty);

		/** a recording's ended: its file once packed ({@code packed}), why, what its scene moment is made from (null:
		 *  none, as for one stopped in the Wilderness), and whether it goes to the page by itself with "Put each encounter
		 *  on my page" on ({@link #sendsByItself}); on the client's thread (11/21/2026, "Encounters, round two") */
		void ended(String packed, EncounterScene.Taken taken, String reason, boolean byItself);

		/** an item's GE price (RuneLite's own) and high alchemy value, each, as the Ground Items plugin reads them (a
		 *  noted item's, the item it notes): {ge, ha}; on the client's thread (11/21/2026, round three) */
		long[] prices(int id);

		/** the next frame the client draws, cropped to {@code bounds} on the canvas, as PNG bytes to {@code done} (null:
		 *  none); asked on the client's thread, answered on whichever (11/21/2026, round three: the reward window as the
		 *  player saw it) */
		void picture(java.awt.Rectangle bounds, java.util.function.Consumer<byte[]> done);
	}

