	Encounters(Client client, net.runelite.client.callback.ClientThread clientThread, Gson gson, Host host)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.gson = gson;
		this.host = host;
	}

	boolean running()
	{
		return recording != null;
	}

	/** the file being written now, or null */
	String writing()
	{
		EncounterFiles.Writer r = recording;
		return r == null ? null : r.fileName();
	}

	/** the files being written or packed (the size cap and the side tab's ✕ leave them alone) */
	Set<String> busy()
	{
		Set<String> s = new HashSet<>();
		EncounterFiles.Writer r = recording;
		if (r != null)
		{
			s.add(r.fileName());
		}
		for (EncounterFiles.Writer f : finishing)
		{
			s.add(f.fileName());
		}
		return s;
	}

	/** the packing still under way (closing the client waits for it) */
	List<Future<?>> packing()
	{
		List<Future<?>> l = new ArrayList<>();
		for (EncounterFiles.Writer f : finishing)
		{
			if (f.finished() != null)
			{
				l.add(f.finished());
			}
		}
		return l;
	}

	// ---- starting and stopping (the client's thread)

	/** "Record now" (the side tab, on the client's thread): a recording by hand, named after where they are. Returns why
	 *  not, or null. */
	String startByHand()
	{
		if (recording != null)
		{
			return null;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return "log in first";
		}
		if (danger())
		{
			return "never in the Wilderness, a PvP area or on a PvP world";
		}
		handStopped = null;
		start(unnamedLabel(), false, null, Collections.emptySet(), 1, null, null, 0);
		return null;
	}

	/** "Stop" (the side tab): the recording running stopped; one started by an area doesn't start again till they've
	 *  left it. */
	void stopByHand()
	{
		if (recording != null)
		{
			if (automatic && area != null)
			{
				handStopped = area;
			}
			stop("stopped by hand", false);
		}
	}

	/** The plugin's off, or the client's closing: the recording stops. */
	void shutDown(String why)
	{
		if (recording != null)
		{
			stop(why, false);
		}
	}

	/** A new recording; for the next part of one split at the length limit, {@code keep} is its scene (its frames and
	 *  anchors go on: the moment is the whole recording's) and {@code base} the ticks of the parts before. */
	private void start(String name, boolean auto, Presence.Area at, Set<Integer> watched, int partNo, String follows,
		EncounterScene keep, int base)
	{
		if (name == null || name.trim().isEmpty())
		{
			name = unnamedLabel();
		}
		label = name;
		automatic = auto;
		area = at;
		watchedIds = watched;
		watchedIndices.clear();
		sinceWatched = 0;
		outside = 0;
		endAt = -1;
		endWhy = null;
		part = partNo;
		partBase = base;
		if (keep == null)
		{
			// (a new encounter: nothing of the last one's raid or loot)
			raidDone = -1;
			raidOver = false;
			looted.clear();
			corpseOf = null;
			waitingFor = null;
			delve = false;
			delveClaimed = false;
			delveOut = 0;
			delveLeave = -1;
			petAt = -1;
			petWaiting = false;
			petChat = null;
			destroyIndex = -1;
			destroyTick = -1;
			runKill = -1;
			runOut = 0;
			bossFought.clear();
			bossDeadAt = -1;
			bossDeadIndex = -1;
			bossDeadName = null;
			lastFight = -1;
			bossSeenAt = 0;
			noCredit = false;
			shots.clear();
			shotsTaken.clear();
			shown.clear();
			shotNo = 0;
		}
		recording = new EncounterFiles.Writer(gson, () -> host.folder().joinSegment("encounters"), name, LocalDateTime.now());
		scene = keep != null ? keep : new EncounterScene(client, host::itemLabel, host.otherPlayers());
		definedNpcs.clear();
		definedObjects.clear();
		definedItems.clear();
		moveSets.clear();
		lastFrames.clear();
		// Fixed for the whole recording, so a file never switches halfway between with and without players
		players = host.otherPlayers();
		seenProjectiles.clear();
		lastDestination = null;

		JsonObject header = emit("header");
		header.addProperty("format", FORMAT_VERSION);
		header.addProperty("label", name);
		header.addProperty("automatic", auto);
		header.addProperty("revision", client.getRevision());
		header.addProperty("world", client.getWorld());
		JsonArray worldTypes = new JsonArray();
		client.getWorldType().forEach(type -> worldTypes.add(type.name()));
		header.add("worldTypes", worldTypes);
		header.addProperty("startedMs", System.currentTimeMillis());
		header.addProperty("startTick", client.getTickCount());
		header.addProperty("otherPlayers", players);
		header.addProperty("playerNames", true);
		header.addProperty("localChat", true);
		header.addProperty("sceneLayout", true);
		header.addProperty("vars", true);
		header.addProperty("canvasW", client.getCanvasWidth());
		header.addProperty("canvasH", client.getCanvasHeight());
		header.addProperty("resized", client.isResized());
		// (Outside's own fields)
		header.addProperty("recorder", "outside");
		header.addProperty("recorderVersion", host.version());
		Player me = client.getLocalPlayer();
		if (me != null && me.getName() != null)
		{
			header.addProperty("player", Text.removeTags(me.getName()).replace(' ', ' '));
		}
		if (at != null)
		{
			header.addProperty("area", at.name);
		}
		else if (run != null)
		{
			// (a run's: its own name, as the area is a boss's; round six)
			header.addProperty("area", run.name);
		}
		if (partNo > 1)
		{
			header.addProperty("part", partNo);
			header.addProperty("follows", follows);
		}

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			startingState();
		}
		log.debug("outside: encounter {} started", recording.fileName());
		host.recording(words(), true);
	}

	/** What the game is as the recording begins: his start snapshot, then Outside's starting state. */
	private void startingState()
	{
		dumpScene();
		WorldView wv = client.getTopLevelWorldView();
		for (NPC npc : wv.npcs())
		{
			npcSpawned(npc, true);
		}
		if (client.getLocalPlayer() != null)
		{
			look(client.getLocalPlayer());
		}
		if (players)
		{
			for (Player player : wv.players())
			{
				if (player != client.getLocalPlayer())
				{
					JsonObject spawn = emit("player_spawn");
					spawn.add("who", EncounterSnap.ref(client, player));
					nameOf(spawn, player);
					look(player);
				}
			}
		}
		emit("ui_tab").addProperty("tab", client.getVarcIntValue(VarClientID.TOPLEVEL_PANEL));
		containers(client.getItemContainer(InventoryID.INV), "inv");
		containers(client.getItemContainer(InventoryID.WORN), "worn");
		invBefore = counts(client.getItemContainer(InventoryID.INV));
		for (Skill skill : Skill.values())
		{
			JsonObject s = emit("stat");
			s.addProperty("skill", skill.name());
			s.addProperty("xp", client.getSkillExperience(skill));
			s.addProperty("level", client.getRealSkillLevel(skill));
			s.addProperty("boosted", client.getBoostedSkillLevel(skill));
		}
		// (Outside's: the varps already set, as var lines of a whole varp)
		if (!bankPinShowing())
		{
			int[] varps = client.getVarps();
			for (int i = 0; varps != null && i < varps.length; i++)
			{
				if (varps[i] != 0)
				{
					JsonObject v = emit("var");
					v.addProperty("varp", i);
					v.addProperty("varbit", -1);
					v.addProperty("value", varps[i]);
					v.addProperty("init", true);
				}
			}
		}
		// (the ground items already lying in the scene, as his item lines)
		Scene scene = wv.getScene();
		Tile[][][] tiles = scene.getTiles();
		for (Tile[][] plane : tiles)
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					List<TileItem> items = tile == null ? null : tile.getGroundItems();
					if (items == null)
					{
						continue;
					}
					for (TileItem item : items)
					{
						defineItem(item.getId());
						JsonObject line = emit("item");
						line.addProperty("id", item.getId());
						line.addProperty("qty", item.getQuantity());
						EncounterSnap.tile(line, wv, tile.getLocalLocation(), tile.getPlane());
						line.addProperty("init", true);
					}
				}
			}
		}
		// (the graphics already on tiles, and the projectiles already in flight)
		for (GraphicsObject gfx : wv.getGraphicsObjects())
		{
			if (!gfx.finished())
			{
				gfxLine(gfx).addProperty("init", true);
			}
		}
		for (Projectile proj : client.getProjectiles())
		{
			if (seenProjectiles.add(proj))
			{
				JsonObject line = emit("proj");
				EncounterSnap.projectile(line, client, wv, proj);
				line.addProperty("init", true);
			}
		}
		// (each animated object as it is now, so only a change from here is written)
		animated.clear();
		scanObjects(false);
	}

	/**
	 * Stops the recording: its end line, then it's closed and packed on its own thread. {@code dropTick}: the lines of
	 * the tick under way never written (somewhere dangerous).
	 */
	private void stop(String reason, boolean dropTick)
	{
		stop(reason, dropTick, false);
	}

	/**
	 * Whether a recording that ended so goes to the page by itself, with "Put each encounter on my page" on (11/22/2026,
	 * Jace: "upload by itself only when the fight had a result"; "i would consider teleporting out when the boss is alive
	 * a failure"). A result: a kill (with credit or without), a completion, a chest looted or claimed, the player's death,
	 * a run failed, and leaving once they'd fought (any hitsplat on them or by them in it: a teleport out with the boss
	 * up). Not one: the open area's quiet ("the fight stopped"), leaving before any fight (an instance walked into and
	 * out of), watched NPCs gone, the three-hour limit, logging out or hopping, the client closed, the plugin turned off.
	 * One started by hand (Record now) goes however it ended: they chose to record it. Never from anywhere dangerous.
	 * Every recording stays on the computer either way, for Put on my page.
	 */
	static boolean sendsByItself(String reason, boolean automatic, boolean fought)
	{
		if (reason == null || "the Wilderness or PvP".equals(reason) || SPLIT.equals(reason))
		{
			return false;
		}
		if (!automatic)
		{
			return true;
		}
		switch (reason)
		{
			case "killed":
			case "completed":
			case "looted":
			case "claimed":
			case "died":
			case "failed":
			case "stopped by hand":
				return true;
			case "left":
				return fought;
			default:
				return false;
		}
	}

	/** {@code split}: the part ends at the length limit and the next goes on (its scene kept, no moment yet, and nothing
	 *  sent: the parts go up joined, as one, once the last has ended; EncounterShelf.prepare). */
	private void stop(String reason, boolean dropTick, boolean split)
	{
		EncounterFiles.Writer stopped = recording;
		if (dropTick)
		{
			stopped.dropPending();
		}
		JsonObject end = emit("end");
		end.addProperty("reason", reason);
		if (noCredit && "killed".equals(reason))
		{
			// (the boss died with no count line: another player's kill credit; 11/22/2026)
			end.addProperty("credit", false);
		}
		end.addProperty("ticks", stopped.ticks());
		end.addProperty("endedMs", System.currentTimeMillis());
		// (its scene moment's makings: nothing from anywhere dangerous; the rest built on the plugin's moment thread)
		EncounterScene.Taken taken = null;
		if (scene != null && !dropTick && !split)
		{
			try
			{
				taken = scene.finish(partBase + stopped.ticks() - 1);
			}
			catch (RuntimeException e)
			{
				log.warn("outside: the encounter's scene couldn't be taken", e);
				taken = EncounterScene.none("its scene couldn't be taken: " + e);
			}
		}
		else if (!dropTick && !split)
		{
			taken = EncounterScene.none("no scene was taken");
		}
		if (taken != null && taken.none != null)
		{
			// (round eight: the upload says why, and the owner's page makes one from the recording when it can)
			log.info("outside: encounter {} has no scene moment: {}", stopped.fileName(), taken.none);
		}
		else if (taken != null && taken.cutFrom >= 0)
		{
			log.info("outside: encounter {}'s moment cut at a map load to ticks {}-{}", stopped.fileName(), taken.cutFrom, taken.cutTo);
		}
		if (!split)
		{
			scene = null;
			// (a delve ended, however: Doom's forms still about while the player falls or leaves start none again till
			// they're out of its instance; round four)
			if (delve)
			{
				delveStopped = true;
			}
			// (a run ended, however: none starts again till they're out of its instance; round six)
			if (run != null)
			{
				runStopped = true;
				run = null;
			}
		}
		host.ended(stopped.fileName() + EncounterFiles.EXT, taken, reason, !split && sendsByItself(reason, automatic, lastFight >= 0));
		finishing.add(stopped);
		recording = null;
		stopped.close(packed ->
		{
			finishing.remove(stopped);
			host.filesChanged(packed);
		});
		log.debug("outside: encounter {} stopped: {}", stopped.fileName(), reason);
		host.recording(null, false);
	}

	/** A part at the length limit ended, and the next begun at once (Outside's: his stops there). */
	private void split()
	{
		// (the part before as it'll be once packed, a moment from now)
		String follows = recording.fileName() + EncounterFiles.EXT;
		boolean auto = automatic;
		Presence.Area at = area;
		Set<Integer> watched = watchedIds;
		Set<Integer> indices = new HashSet<>(watchedIndices);
		String name = label;
		int next = part + 1;
		int base = partBase + recording.ticks();
		EncounterScene kept = scene;
		stop(SPLIT, false, true);
		start(name, auto, at, watched, next, follows, kept, base);
		watchedIndices.addAll(indices);
	}

	private String words()
	{
		EncounterFiles.Writer r = recording;
		if (r == null)
		{
			return null;
		}
		int s = r.ticks() * 6 / 10;
		return String.format("%s%s · %d:%02d · %,d KB%s", label, part > 1 ? " (part " + part + ")" : "", s / 60, s % 60,
			r.bytesWritten() / 1024, r.hasFailed() ? " · writing failed: see the client's log" : "");
	}

	// ---- where they are

	/** In the Wilderness, a PvP area, or on a PvP or Deadman world (OutsidePlugin.held, the snapshot's rule). */
	private boolean danger()
	{
		Player me = client.getLocalPlayer();
		WorldPoint at = OutsidePlugin.here(client, me);
		int x = at == null ? -1 : at.getX(), y = at == null ? -1 : at.getY(), region = at == null ? -1 : at.getRegionID();
		EnumSet<WorldType> types = client.getWorldType();
		boolean pvpWorld = WorldType.isPvpWorld(types) || types.contains(WorldType.DEADMAN);
		boolean wild = OutsidePlugin.wilderness(x, y, client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1);
		boolean pvpArea = OutsidePlugin.pvpArea(x, y, region, client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1);
		return OutsidePlugin.held(pvpWorld, wild, pvpArea);
	}

	/** The boss's or raid's area they stand in, as Discord names it (an instance's by its template), or null; not the
	 *  skilling bosses Discord lists with the rest, where a recording would run as long as they skill. */
	private Presence.Area bossArea()
	{
		return recordedArea(here());
	}

	/**
	 * Whether an area of Discord's is one a recording starts at by itself (11/22/2026, the table, EncounterBosses): a boss's
	 * or a raid's, and the minigames that are a boss fight (Barrows, the Inferno, the Fight Cave); not the skilling bosses,
	 * a lobby, a raid's part, or a run's minigame (the Gauntlets and the Colosseum start by their own rule). The area, or
	 * null.
	 */
	static Presence.Area recordedArea(Presence.Area a)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.area != null && b.start != EncounterBosses.Start.NEVER && b.start != EncounterBosses.Start.OWN
			&& !SKILLING.contains(a.name) && !LOBBIES.contains(a.name) && !RAID_PARTS.containsKey(a.name) ? a : null;
	}

	/** Whether where they are ({@code now}) is the area a recording started at: the same, one of the same name, or a part
	 *  of it (Tombs of Amascut's treasure room). */
	static boolean sameArea(Presence.Area now, Presence.Area area)
	{
		return now != null && area != null && (now == area || now.name.equals(area.name) || area.name.equals(RAID_PARTS.get(now.name)));
	}

	/** The raid they're in, for the recording's endings: the one that started it, else the raid they stand in (a part of
	 *  one as the raid itself; a lobby isn't one), or null. */
	private Presence.Area raidArea()
	{
		if (area != null)
		{
			return Presence.RAID.equals(area.kind) ? area : null;
		}
		Presence.Area h = here();
		return h != null && Presence.RAID.equals(h.kind) && !LOBBIES.contains(h.name) ? h : null;
	}

	/** Whether a count line in a raid is the raid's own completion ("Your completed Chambers of Xeric count is: 12."),
	 *  not a boss's inside it. */
	static boolean raidCompletion(String text, String counted, String raid)
	{
		if (text != null && text.startsWith("Your completed "))
		{
			return true;
		}
		String c = counted == null ? "" : counted.toLowerCase().replaceFirst("^the ", "");
		String r = raid == null ? "" : raid.toLowerCase().replaceFirst("^the ", "");
		return !c.isEmpty() && !r.isEmpty() && (c.contains(r) || r.contains(c));
	}

	private Presence.Area here()
	{
		Player me = client.getLocalPlayer();
		WorldPoint at = OutsidePlugin.here(client, me);
		WorldView wv = client.getTopLevelWorldView();
		return at == null ? null : areaAt(at.getRegionID(), at.getPlane(), wv != null && wv.isInstance());
	}

	/**
	 * A raid's rooms Discord's list misses (11/21/2026, round eight; Jace: "Sometimes it also seems like the plugin doesn't
	 * start automatically recording when I enter the fractured archive", and his raids came up in two halves): the
	 * Fractured Archive's first room (the Archive Guardian's) and its Nexus between the bosses are one instanced region,
	 * 16471 (WorldPoint.fromLocalInstance's template; his recordings' scene lines), which RuneLite's Discord plugin
	 * (DiscordGameEventType.RAIDS_THE_FRACTURED_ARCHIVE, 1.13.7: 16214, 16726, 16215, 16727, 16216, 16728, 16472, 16474)
	 * doesn't name. So entering the raid started nothing until the second boss's room, and a wait at the Nexus past
	 * LEFT_RAID's 50 ticks (the Quartermaster's shop) ended it as "left", the rest a recording of its own. Counted only in
	 * an instance (the region's own ground outside one is the raid's lobby's neighbour). Each maps to a region of the raid
	 * Discord does name.
	 */
	static final Map<Integer, Integer> RAID_ROOMS = Collections.singletonMap(16471, 16214);

	/** The area for a region (its template's in an instance), Discord's or a raid's room it misses (RAID_ROOMS). */
	static Presence.Area areaAt(int region, int plane, boolean instance)
	{
		Presence.Area a = Presence.area(region, plane);
		if (a == null && instance && RAID_ROOMS.containsKey(region))
		{
			a = Presence.area(RAID_ROOMS.get(region), plane);
		}
		return a;
	}

	/**
	 * Whether the game itself says the player is still in a raid (11/21/2026, round eight), wherever it's put them: a
	 * raid's own state, as RuneLite's plugins read it. Chambers of Xeric's RAIDS_CLIENT_INDUNGEON (the Raids plugin's
	 * Varbits.IN_RAID) is 1 inside; Theatre of Blood's TOB_CLIENT_PARTYSTATUS (Varbits.THEATRE_OF_BLOOD) is 2 inside and
	 * 3 dead and spectating. Tombs of Amascut and the Fractured Archive have no such state in RuneLite: a dead raider stays
	 * in the room's instance, spectating, until the room ends, then goes on with the party (his files: "You will respawn
	 * when your party completes or fails the challenge", the Nexus next), which the regions cover.
	 */
	private boolean raidSays(Presence.Area raid)
	{
		if (raid == null)
		{
			return false;
		}
		switch (raid.name)
		{
			case "Chambers of Xeric":
				return client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
			case "Theatre of Blood":
				int st = client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS);
				return st == 2 || st == 3;
			default:
				return false;
		}
	}

	/** The game's lines that end a raid for the player while the party may go on without them (11/21/2026, round eight;
	 *  his Fractured Archive files): every raider dead ("You failed to survive the Fractured Archive."), or one put out of
	 *  it ("You were unable to rejoin your party."). The first ticks out of the raid after one is the end. */
	static final Pattern RAID_OVER_LINE = Pattern.compile("^(?:You failed to survive the .+\\.|You were unable to rejoin your party\\.)$");

	/**
	 * A name for a recording: the area they're in, as Discord names it, or else the highest-level NPC around (usually the
	 * boss), or else the nearest NPC; empty if there's none of those ("session"). (His names a place from his own copy of
	 * the Discord plugin's list; this one is Presence's.)
	 */
	private String unnamedLabel()
	{
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (me == null || wv == null)
		{
			return "";
		}
		Presence.Area a = here();
		if (a != null)
		{
			return a.name;
		}
		NPC strongest = null;
		NPC nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (NPC npc : wv.npcs())
		{
			String name = npc.getName();
			if (name == null || name.equals("null"))
			{
				continue;
			}
			if (npc.getCombatLevel() > 0 && (strongest == null || npc.getCombatLevel() > strongest.getCombatLevel()))
			{
				strongest = npc;
			}
			int distance = npc.getWorldLocation().distanceTo(me.getWorldLocation());
			if (distance < nearestDistance)
			{
				nearest = npc;
				nearestDistance = distance;
			}
		}
		NPC named = strongest != null ? strongest : nearest;
		return named == null ? "" : Text.removeTags(named.getName());
	}

	static Set<Integer> parseIds(String text)
	{
		Set<Integer> ids = new HashSet<>();
		for (String part : Text.fromCSV(text == null ? "" : text))
		{
			try
			{
				ids.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException e)
			{
				// (not a number: left out)
			}
		}
		return Collections.unmodifiableSet(ids);
	}

	/** May one start by itself now: switched on, a page, logged in, nowhere dangerous. */
	private boolean mayStart()
	{
		return recording == null && host.autoOn() && host.hasPage() && client.getGameState() == GameState.LOGGED_IN && !danger();
	}

	/** the whole recording's tick (every part's): the scene's and the endings' clock */
	private int whole()
	{
		return partBase + (recording == null ? 0 : recording.ticks());
	}

	private JsonObject emit(String event)
	{
		JsonObject line = EncounterSnap.line(event, recording.ticks(), client.getGameCycle());
		recording.add(line);
		return line;
	}

	/**
	 * Closing the window doesn't log out first, so a recording still running is stopped here. The client waits (up to
	 * 10 seconds, shared with other plugins) for it and any still packing to finish; if it can't, the plain file is left
	 * whole and packed the next time the plugin starts (his)
	 */
	@Subscribe
	public void onClientShutdown(net.runelite.client.events.ClientShutdown event)
	{
		java.util.concurrent.CompletableFuture<Void> stopped = new java.util.concurrent.CompletableFuture<>();
		clientThread.invoke(() ->
		{
			if (recording != null)
			{
				stop("client closed", false);
			}
			// Queued before stopped completes, so the client waits for these too
			for (Future<?> packed : packing())
			{
				event.waitFor(packed);
			}
			stopped.complete(null);
		});
		event.waitFor(stopped);
	}

	// ---- each tick and each client cycle

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickNow++;
		if (recording == null)
		{
			autoStartByArea();
			return;
		}
		// (somewhere dangerous: stopped, this tick's lines never written)
		if (danger())
		{
			stop("the Wilderness or PvP", true);
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (scene != null)
		{
			scene.tick(whole());
		}
		JsonObject tick = emit("tick");
		tick.addProperty("abs", client.getTickCount());
		tick.addProperty("ms", System.currentTimeMillis());

		Player me = client.getLocalPlayer();
		if (me != null)
		{
			tick.add("me", self(me));
			moves(me);
		}
		tick.add("ui", ui());

		boolean watchedSeen = false;
		// (a boss's own place: whether any of its NPCs is in sight, for its leaving; 11/22/2026)
		EncounterBosses.Boss own = automatic && placeless(area) ? EncounterBosses.forArea(area) : null;
		JsonArray npcs = new JsonArray();
		for (NPC npc : wv.npcs())
		{
			npcs.add(EncounterSnap.actor(client, npc));
			moves(npc);
			if (own != null && own.isBoss(nameOf(npc)))
			{
				bossSeenAt = whole();
			}
			if (watchedIds.contains(npc.getId()))
			{
				watchedIndices.add(npc.getIndex());
			}
			// (Doom of Mokhaiotl about: a delve, however this recording started; round four)
			delve |= DOOM_IDS.contains(npc.getId());
			watchedSeen |= watchedIds.contains(npc.getId()) || watchedIndices.contains(npc.getIndex());
		}
		tick.add("npcs", npcs);

		if (players)
		{
			JsonArray others = new JsonArray();
			for (Player player : wv.players())
			{
				if (player != me)
				{
					others.add(EncounterSnap.actor(client, player));
					moves(player);
				}
			}
			tick.add("players", others);
		}
		scanObjects(true);
		spawnedThisTick.clear();
		recording.endTick();

		// (a reward window open whose inventory hadn't filled yet: read again, then let go; round three)
		if (waitingFor != null)
		{
			Chest w = waitingFor;
			List<int[]> got = itemsOf(client.getItemContainer(w.inv));
			if (!got.isEmpty())
			{
				loot(w.source, got, w.window, false);
			}
			else if (whole() > waitingUntil)
			{
				waitingFor = null;
				// (its window was shown all the same, empty as it was drawn: its `window` line; round five)
				shoot("chest", w.window, null, new ArrayList<>(), -1, false, null);
			}
		}

		// (a chat line's or the inventory's picture let go by now; round five)
		shotsExpire();

		// (a pet's line: the pet looked for beside them, as the follower that wasn't out before; round four)
		if (petWaiting)
		{
			petLook();
		}

		// (how it ends: the kill or a death a few ticks on, leaving, the listed NPCs gone)
		if (endAt >= 0 && whole() >= endAt && petHolds())
		{
			// (a pet's come: held till it's seen and a few ticks more, so the moment has it; round four)
		}
		else if (endAt >= 0 && whole() >= endAt)
		{
			// (a kill with no drop yet: held a little for it, the moment's anchor (11/21/2026); and a corpse to loot, till
			// it's looted or goes (round three: Araxxor's, as the game's own loot needs a click on what's left))
			boolean unlooted = "killed".equals(endWhy) && scene != null && scene.killed() && !scene.dropped() && !scene.looted();
			boolean waiting = unlooted && (whole() < scene.killTick() + DROP_WAIT || corpseWaiting());
			if (!waiting)
			{
				stopAuto(endWhy);
				return;
			}
		}
		if (automatic && delve)
		{
			// (a delve (Jace, 11/21/2026): every level one recording, through each level's end, its window and the descent;
			// it ends with the player's death (above), or the claim and the burrow's Leave a few ticks on (its click),
			// or the claim and out of the delve's instance; unclaimed and out of it a while, a teleport: left)
			delveOut = client.getTopLevelWorldView().isInstance() ? 0 : delveOut + 1;
			if (endAt < 0 && delveClaimed && delveOut > DELVE_LEFT)
			{
				stopAuto("claimed");
				return;
			}
			if (endAt < 0 && !delveClaimed && delveOut > DELVE_OUT)
			{
				stopAuto("left");
				return;
			}
			if (whole() >= RAID_MOST)
			{
				stopAuto("the time limit");
				return;
			}
		}
		else if (automatic && run != null)
		{
			String why = runEnds();
			if (why != null)
			{
				stopAuto(why);
				return;
			}
		}
		else if (automatic && area != null && own != null)
		{
			// (a boss Discord has no area for, started by its fight: left once none of its NPCs has been in sight a while
			// (the moons aren't between fights: not theirs); then as a boss's area below; 11/22/2026)
			if (endAt < 0 && own.goneEnds(whole(), bossSeenAt))
			{
				stopAuto("left");
				return;
			}
			if (bossEnds(own))
			{
				return;
			}
		}
		else if (automatic && area != null)
		{
			Presence.Area now = here();
			boolean raid = Presence.RAID.equals(area.kind);
			EncounterBosses.Boss row = EncounterBosses.forArea(area);
			// (a raid's own state counts as in it, wherever a dead raider's been put; round eight)
			boolean in = sameArea(now, area) || raid && !raidOver && raidSays(area);
			outside = in ? 0 : outside + 1;
			// (a raid is whole from entering to leaving its treasure room (Jace, 11/21/2026): its completion line, a
			// room's "Challenge complete", a sub-boss's count, the loot and a death all go on; once it's completed or
			// looted, the first ticks out of it are the end, the click on the exit and the map leaving the raid)
			boolean done = raid && (raidDone >= 0 || !looted.isEmpty());
			// (the raid over for them, failed or put out of it: the first ticks out are the end too; round eight)
			if (!in && raid && raidOver && now == null && outside > LEFT_BOSS)
			{
				stopAuto("failed");
				return;
			}
			// (in an area of another name: left at once; where no area's named, after a few ticks, a raid's longer
			// before it's done: a room the list misses, a map loading)
			// (a kill or a death already due ends as itself: the Fight Cave's Jad, then out of the cave before the kill's
			// few ticks were up, is a kill, not a leaving; 11/22/2026. The Inferno's and the Fight Cave's waves wait longer
			// in no named area, as a raid does: the table's grace)
			if (!in && (now != null || outside > (raid && !done ? LEFT_RAID : row != null ? row.grace : LEFT_BOSS)))
			{
				stopAuto(done ? "completed" : endAt >= 0 && endWhy != null ? endWhy : "left");
				return;
			}
			if (raid && raidDone >= 0 && whole() >= raidDone + RAID_AFTER)
			{
				stopAuto("completed");
				return;
			}
			if (raid && whole() >= RAID_MOST)
			{
				stopAuto("the time limit");
				return;
			}
			if (!raid && bossEnds(row))
			{
				return;
			}
		}
		else if (automatic)
		{
			sinceWatched = watchedSeen ? 0 : sinceWatched + 1;
			if (sinceWatched >= WATCHED_GONE)
			{
				stopAuto("watched NPCs gone");
				return;
			}
		}
		if (recording.ticks() >= PART_TICKS)
		{
			split();
			return;
		}
		if (recording.ticks() % 5 == 0)
		{
			host.recording(words(), true);
		}
	}

	/** An automatic recording's end: after the kill or a death in the area, the next starts only with the next fight. */
	private void stopAuto(String why)
	{
		Presence.Area a = area;
		stop(why, false);
		if (a != null && ("killed".equals(why) || "died".equals(why) || "completed".equals(why) || "looted".equals(why)
			|| "claimed".equals(why)))
		{
			afterKill = a;
		}
	}

	/**
	 * A boss's area's (or its own place's) endings each tick, besides leaving it: the boss they fought dead with no count
	 * line (no kill credit, 11/22/2026), and the player out of combat a few ticks: killed all the same, held for a drop
	 * as a count line's kill is (only where the table lets a death end it: not a phase, a wave, a brother before the
	 * chest); and where it started by the fight, the fight given up, the boss never killed ("the fight stopped",
	 * 11/22/2026: an open area has no leaving). Whether it stopped.
	 */
	private boolean bossEnds(EncounterBosses.Boss row)
	{
		if (row == null)
		{
			return false;
		}
		if (endAt < 0 && !row.deaths.isEmpty() && bossDown(whole(), bossDeadAt, lastFight) && !otherBossUp(null))
		{
			endAt = whole();
			endWhy = "killed";
			noCredit = true;
			if (scene != null)
			{
				scene.kill(bossDeadAt, bossDeadName);
			}
		}
		if (endAt < 0 && row.idleEnds(instance(), whole(), lastFight))
		{
			stopAuto("the fight stopped");
			return true;
		}
		return false;
	}

	/** Not recording: at a boss's or a raid's area, one starts (not again where one was stopped by hand, or just ended by
	 *  its kill, till the next fight there). */
	private void autoStartByArea()
	{
		if (autoStartRun())
		{
			return;
		}
		if (delveStopped && client.getGameState() == GameState.LOGGED_IN && !client.getTopLevelWorldView().isInstance())
		{
			delveStopped = false;
		}
		Presence.Area a = client.getGameState() == GameState.LOGGED_IN ? bossArea() : null;
		if (a == null || lastArea == null || !a.name.equals(lastArea.name))
		{
			// (left, or somewhere new: what waited there is forgotten; a boss's own place stopped by hand, once none of its
			// NPCs is in sight: it has no area to leave, 11/22/2026)
			if (!placeless(handStopped) || !placeAround(handStopped))
			{
				handStopped = null;
			}
			afterKill = null;
		}
		lastArea = a;
		if (a == null || !mayStart() || a == handStopped || a == afterKill || !startsOnEntry(a, instance()))
		{
			return;
		}
		start(a.name, true, a, Collections.emptySet(), 1, null, null, 0);
	}

	// ---- an open boss area, and the boss's own death (11/22/2026; Jace at the Giant Mole on update 6's build:
	// "recording started when i entered moles lair (non-instanced location with option of instance, i entered
	// non-instanced location) ... people spend hours here so probably not ideal", and "it looks like the recording is not
	// stopping after i kill the mole": someone else had hit the Mole first, so his ironman got no kill credit and no
	// count line, and nothing else ends a recording in a lair with no leaving)
	//
	// (11/22/2026, later: every boss, raid and boss-type minigame in one table, EncounterBosses, read for each decision
	// below; plugin/docs/encounter-bosses.md. What it changed: the Inferno, the Fight Cave and Barrows record (Discord
	// names them minigames, so nothing started there); the bosses Discord has no area for (Scurrius, the Hueycoatl,
	// Amoxliatl, the Moons of Peril, the King Black Dragon, Brutus, the Mad Angel, the Maggot King, the shellbane gryphon,
	// Obor, Bryophyta, the Mimic, the Deranged archaeologist, TzHaar-Ket-Rak's challenges) start with their fight,
	// wherever it is; the Dagannoth Kings (a count line a king) end with the last one fought, and a corpse to loot (a
	// Royal Titan's) is never a boss still up;
	// a wave's or a moon's count line, or a brother's death, never ends a run whose end is its last boss or its chest; the
	// Kalphite Queen's first form falling is a phase, not her death; a kill whose leaving came before its few ticks were
	// up ends as the kill, not "left"; an agility lap's count line is no kill)

	/** the NPCs that are an area's boss where Discord's name for the area isn't theirs (any other area's boss is the NPC
	 *  of the area's own name): Discord's boss areas' rows in the table (EncounterBosses), the cache's names */
	static final Map<String, Set<String>> BOSS_NPCS;

	static
	{
		Map<String, Set<String>> m = new HashMap<>();
		for (EncounterBosses.Boss b : EncounterBosses.ALL)
		{
			Presence.Area d = b.area == null ? null : EncounterBosses.discord(b.area);
			if (d != null && Presence.BOSS.equals(d.kind) && !b.npcs.equals(Collections.singleton(EncounterBosses.norm(b.area))))
			{
				m.put(b.area, b.npcs);
			}
		}
		BOSS_NPCS = Collections.unmodifiableMap(m);
	}

	/** after the boss the player fought dies with no count line (no kill credit: another player's hit first), the ticks
	 *  before the recording ends, and the ticks with no hitsplat on or from the player (out of combat) it also needs */
	static final int BOSS_DOWN = 5, QUIET = 8;
	/** in an open boss area, ticks with no hitsplat on or from the player before the fight counts as given up ("the
	 *  fight stopped"): the Mole dug in and chased takes 40 s or so (ActivityTest), and they may stay for hours */
	static final int OPEN_IDLE = 150;

	/** An open boss area: a boss's (not a raid's) and not an instance (the Giant Mole's lair entered without its
	 *  instance's option), or one whose boss's fight always starts it (Barrows, a boss's own place: the table's FIGHT).
	 *  There a recording starts with the fight with the boss, not on entering. */
	static boolean openArea(Presence.Area a, boolean instance)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.startsByFight(instance);
	}

	/** Whether an area starts its recording the tick they're in it: a raid, a boss's in an instance, the Inferno and the
	 *  Fight Cave. */
	static boolean startsOnEntry(Presence.Area a, boolean instance)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.startsOnEntry(instance);
	}

	/** Whether an NPC of this name is the area's boss (the table's names, else the area's own name), any case. */
	static boolean bossOf(Presence.Area a, String npc)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.isBoss(npc);
	}

	/** Whether a fight (the player's hitsplat on it, its hitsplat on the player, the player attacking it) with an NPC of
	 *  this name starts a recording: an open boss area's boss. */
	static boolean startsByFight(Presence.Area a, boolean instance, String npc)
	{
		return openArea(a, instance) && bossOf(a, npc);
	}

	/** A boss Discord has no area for, whose fight starts a recording wherever it is (11/22/2026: Scurrius, the Hueycoatl,
	 *  the Moons of Peril, the King Black Dragon...): the place named for it that the recording is of, or null. Never in
	 *  the Wilderness (mayStart). */
	static Presence.Area placeOf(String npc)
	{
		EncounterBosses.Boss b = EncounterBosses.placeless(npc);
		return b == null ? null : b.place;
	}

	/** Whether an area is a boss's own place (placeOf's), not one of Discord's. */
	static boolean placeless(Presence.Area a)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.place != null && b.place == a;
	}

	/** The name a count line counts ("Your Vorkath kill count is: 418." counts "Vorkath"; "Your Bryophyta chests opened
	 *  count is: 5." counts "Bryophyta"; "Your completion count for TzHaar-Ket-Rak's First Challenge is: 1." counts the
	 *  challenge), or null: not a count line, or one that's no fight's (a lap's, a ticket's, a harvest's). */
	static String killName(String text)
	{
		if (text == null || NOT_A_KILL.matcher(text).matches())
		{
			return null;
		}
		Matcher m = KILL_LINE.matcher(text);
		if (!m.matches())
		{
			m = CHALLENGE_LINE.matcher(text);
			if (!m.matches())
			{
				return null;
			}
		}
		return EncounterBosses.counted(m.group(1));
	}

	/** A count line in a recording started at {@code a} (null: by hand, or by a listed NPC): why it ends it ("killed",
	 *  "completed" for the last wave's, "looted" for a chest's), or null: no count line, a wave's, a sub-boss's, a moon's
	 *  before the chest, one of several bosses with another fought still up ({@code otherUp}), or a raid's, a run's or a
	 *  delve's (their own rules'). */
	static String killEnds(Presence.Area a, String text, boolean otherUp)
	{
		String counted = killName(text);
		if (counted == null)
		{
			return null;
		}
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b == null ? "killed" : b.killEnds(counted, otherUp);
	}

	/** Whether this NPC's death (its id and name), fought, ends a recording started at {@code a} with no count line: one of
	 *  its bosses whose death is the end, not a phase (the Kalphite Queen's first form), and never where the line always
	 *  comes or the end is a chest's (the waves, Barrows' brothers, the moons, Obor's and Bryophyta's chests). */
	static boolean deathEnds(Presence.Area a, int id, String npc)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && !Presence.RAID.equals(b.kind) && b.diesTo(id, npc);
	}

	/** Whether a recording started at {@code a} ends for the fight given up ("the fight stopped"): where it started by the
	 *  fight, the row's idle ticks with no hitsplat on or from the player (OPEN_IDLE in an open boss area). */
	static boolean idleEnds(Presence.Area a, boolean instance, int now, int lastFight)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(a);
		return b != null && b.idleEnds(instance, now, lastFight);
	}

	/** Whether a recording whose boss died with no count line ({@code deadAt}, the whole recording's tick, -1 none) ends
	 *  now: BOSS_DOWN ticks after the death and QUIET after the last hitsplat on or from the player ({@code lastFight}). */
	static boolean bossDown(int now, int deadAt, int lastFight)
	{
		return deadAt >= 0 && now >= deadAt + BOSS_DOWN && now >= lastFight + QUIET;
	}

	/** Whether a recording in an open boss area ends for the fight given up: OPEN_IDLE ticks with no hitsplat on or from
	 *  the player ({@code lastFight}, the whole recording's tick). */
	static boolean fightStopped(int now, int lastFight)
	{
		return now >= lastFight + OPEN_IDLE;
	}

	private boolean instance()
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv != null && wv.isInstance();
	}

	private static String nameOf(Actor a)
	{
		return a == null || a.getName() == null ? null : Text.removeTags(a.getName());
	}

	/** The area's boss fighting the player (interacting with them), or null; with no area, a boss whose own place starts
	 *  by its fight (placeOf). */
	private NPC bossOnMe(Presence.Area a)
	{
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (me == null || wv == null)
		{
			return null;
		}
		for (NPC npc : wv.npcs())
		{
			if (npc.getInteracting() == me && (a != null ? bossOf(a, nameOf(npc)) : placeOf(nameOf(npc)) != null))
			{
				return npc;
			}
		}
		return null;
	}

	/** Not recording, in an open boss area (or by a boss whose own place it is, by its name): the fight with its boss
	 *  ({@code npc}) starts one; each kill there its own (not again where one was stopped by hand, till they've left). */
	private void fightOpen(NPC npc)
	{
		if (npc == null || !mayStart())
		{
			return;
		}
		Presence.Area a = bossArea();
		if (a == null)
		{
			// (no recorded area of Discord's here: a boss whose own place it is, by its name; 11/22/2026)
			a = placeOf(nameOf(npc));
		}
		if (a == null || a == handStopped || !startsByFight(a, instance(), nameOf(npc)))
		{
			return;
		}
		afterKill = null;
		start(a.name, true, a, Collections.emptySet(), 1, null, null, 0);
		bossFought.add(npc.getIndex());
		lastFight = whole();
		bossSeenAt = whole();
	}

	/** A recording started by a boss's area (or its own place): an NPC the player fought, the area's boss, is noted. */
	private void fought(NPC npc)
	{
		if (npc != null && automatic && area != null && !Presence.RAID.equals(area.kind) && bossOf(area, nameOf(npc)))
		{
			bossFought.add(npc.getIndex());
		}
	}

	/** The boss the player fought has died (its death, or gone dead): noted for the ending with no count line. */
	private void bossDied(NPC npc)
	{
		if (bossDeadAt < 0 && endAt < 0 && automatic && area != null && bossFought.contains(npc.getIndex())
			&& deathEnds(area, npc.getId(), nameOf(npc)))
		{
			bossDeadAt = whole();
			bossDeadIndex = npc.getIndex();
			bossDeadName = nameOf(npc);
		}
	}

	/** Another of the area's bosses they fought still up beside the dead one (the Dagannoth Kings' brothers, Dusk after
	 *  Dawn, a Royal Titan after the other): the fight goes on. {@code counted}: a count line's name, the one it counts
	 *  (its kill) not counting as up (null: none). */
	private boolean otherBossUp(String counted)
	{
		WorldView wv = client.getTopLevelWorldView();
		EncounterBosses.Boss b = EncounterBosses.forArea(area);
		if (wv == null || b == null)
		{
			return false;
		}
		for (NPC npc : wv.npcs())
		{
			String n = nameOf(npc);
			if (npc.getIndex() != bossDeadIndex && bossFought.contains(npc.getIndex()) && !npc.isDead() && b.isDeath(n)
				&& (counted == null || !EncounterBosses.norm(n).equals(EncounterBosses.norm(counted))) && !isCorpse(npc))
			{
				return true;
			}
		}
		return false;
	}

	/** Whether an NPC is a corpse to loot (a loot option, no Attack: the Royal Titans' and Araxxor's, by its name still),
	 *  not a boss up (11/22/2026; as corpseWaiting tells them). */
	private static boolean isCorpse(NPC npc)
	{
		net.runelite.api.NPCComposition def = npc.getTransformedComposition();
		if (def == null || def.getActions() == null)
		{
			return false;
		}
		boolean loot = false, attack = false;
		for (String act : def.getActions())
		{
			if (act != null)
			{
				String a = Text.removeTags(act);
				loot |= LOOT_OPTIONS.contains(a) || FORFEIT_OPTIONS.contains(a);
				attack |= "Attack".equals(a);
			}
		}
		return loot && !attack;
	}

	/** One of a boss's own place's NPCs (placeless's) in sight now. */
	private boolean placeAround(Presence.Area place)
	{
		EncounterBosses.Boss b = EncounterBosses.forArea(place);
		WorldView wv = client.getTopLevelWorldView();
		if (b == null || wv == null)
		{
			return false;
		}
		for (NPC npc : wv.npcs())
		{
			if (b.isBoss(nameOf(npc)))
			{
				return true;
			}
		}
		return false;
	}

	/** After a kill in the area: the next fight (a hitsplat on them, or on an NPC from them) starts the next one (not in
	 *  an open area, where only the boss's own fight does: fightOpen). */
	private void fightAgain()
	{
		if (afterKill != null && recording == null && mayStart() && bossArea() == afterKill && !openArea(afterKill, instance()))
		{
			Presence.Area a = afterKill;
			afterKill = null;
			start(a.name, true, a, Collections.emptySet(), 1, null, null, 0);
		}
	}

	// ---- a run (round six, 11/21/2026): the Gauntlet, the Corrupted Gauntlet, the Fortis Colosseum

	/** The run whose instance a region (the player's, read as its template) is, or null: only in an instance. */
	static Run runAt(int region, boolean instance)
	{
		if (!instance)
		{
			return null;
		}
		for (Run r : RUNS)
		{
			if (r.region == region)
			{
				return r;
			}
		}
		return null;
	}

	/** The run a click on a way in leads to (the Gauntlet's "Enter-corrupted" is the Corrupted Gauntlet), or null. */
	static Run runEntered(int objectId, String option)
	{
		if (!RUN_ENTRANCES.contains(objectId) || option == null || !option.startsWith("Enter"))
		{
			return null;
		}
		if (objectId == net.runelite.api.gameval.ObjectID.COLOSSEUM_ENTRANCE)
		{
			return COLOSSEUM;
		}
		return "Enter-corrupted".equals(option) ? CORRUPTED : GAUNTLET;
	}

	/** the run's instance the player stands in, or null */
	private Run runHere()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		Player me = client.getLocalPlayer();
		WorldPoint at = OutsidePlugin.here(client, me);
		return at == null ? null : runAt(at.getRegionID(), client.getTopLevelWorldView().isInstance());
	}

	/**
	 * Not recording: in a run's instance, its recording starts (Jace, 11/21/2026: "start recording upon entering the
	 * instance"): the click on its way in, then the map of its instance; arriving without the click seen (the plugin
	 * switched on inside, say) starts it all the same. Not again in the instance a run was ended or stopped in. Whether
	 * they're in one (a listed NPC there doesn't start a recording of its own).
	 */
	private boolean autoStartRun()
	{
		Run r = runHere();
		if (r == null)
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				runStopped = false;
			}
			return false;
		}
		if (!runStopped && mayStart())
		{
			armed = null;
			run = r;
			start(r.name, true, null, Collections.emptySet(), 1, null, null, 0);
		}
		return true;
	}

	/**
	 * Each tick of a run: why it ends now, or null. A Gauntlet: the Hunllef's kill sends them to the lobby, and the run
	 * waits there for the chest (its loot ends it, by loot()), leaving the lobby, or RUN_CHEST_WAIT; out of the instance
	 * with no kill (the platform, the barrier's Escape, an escape crystal): left. The Colosseum: every wave, Sol Heredit's
	 * count line and the claim's window go on (the claim ends it once its window shuts, by onWidgetClosed); out of the
	 * arena: "claimed" after the claim, else left. A death ends either (onActorDeath, as for a boss).
	 */
	private String runEnds()
	{
		boolean in = runHere() == run;
		runOut = in ? 0 : runOut + 1;
		Player me = client.getLocalPlayer();
		WorldPoint at = OutsidePlugin.here(client, me);
		boolean lobby = at != null && at.getRegionID() == GAUNTLET_LOBBY;
		return runEnding(run, in, lobby, runOut, runKill, whole(), !looted.isEmpty(), endAt, endWhy);
	}

	/** runEnds's rule, apart from the game (so the tests can walk a run through it): {@code out} ticks out of the
	 *  instance; {@code lobby} in the Gauntlet's lobby; {@code kill} the run's kill (-1 none); {@code now} the whole
	 *  recording's tick; {@code looted} its loot written; {@code endAt} and {@code endWhy} an ending already due. */
	static String runEnding(Run run, boolean in, boolean lobby, int out, int kill, int now, boolean looted, int endAt,
		String endWhy)
	{
		if (endAt >= 0)
		{
			// (an ending due: the Colosseum's claim made, and out of the arena already, ends it now)
			return "claimed".equals(endWhy) && out > RUN_LEFT ? "claimed" : null;
		}
		if (now >= RAID_MOST)
		{
			return "the time limit";
		}
		if (run.gauntlet && kill >= 0)
		{
			// (killed: the instance left for the lobby is the way to the chest, not leaving)
			return !in && !lobby && out > RUN_LEFT || now >= kill + RUN_CHEST_WAIT ? "completed" : null;
		}
		if (out > RUN_LEFT)
		{
			return looted ? "claimed" : "left";
		}
		return null;
	}

	/** A kill in a run (its count line, or the Hunllef's death): noted, nothing ended. */
	private void runKilled(String counted)
	{
		if (runKill < 0)
		{
			runKill = whole();
		}
		if (scene != null && !scene.killed())
		{
			scene.kill(whole(), counted);
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (recording == null)
		{
			return;
		}
		// (the scene moment's frames: the moving things as the client poses them, every 2 cycles; 11/21/2026)
		if (scene != null)
		{
			scene.cycle();
		}
		// (the windows as the player sees them, each taken from the next frame the client draws once it's laid out: the
		// loot's window for the moment as in round three, and every reward-type window for its `window` line; round five)
		shotsCycle();
		// Where the client is walking you, each time it changes: the tile it puts the red flag on (his dest line,
		// without the click it came from: clicks aren't recorded here)
		LocalPoint destination = client.getLocalDestinationLocation();
		boolean changed = destination != null && !destination.equals(lastDestination);
		lastDestination = destination;
		if (changed && !bankPinShowing())
		{
			JsonObject line = emit("dest");
			EncounterSnap.tile(line, client.getTopLevelWorldView(), destination);
			line.remove("lx");
			line.remove("ly");
		}
		// (Outside's: a projectile over before it moves posts no ProjectileMoved; the client's list has it a cycle)
		WorldView wv = client.getTopLevelWorldView();
		for (Projectile proj : client.getProjectiles())
		{
			if (seenProjectiles.add(proj))
			{
				EncounterSnap.projectile(emit("proj"), client, wv, proj);
			}
		}
		// (Outside's: an animation sent again restarts with no event: its frame back while it hadn't reached its end)
		for (NPC npc : wv.npcs())
		{
			restart(npc);
		}
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			restart(me);
		}
		if (players)
		{
			for (Player p : wv.players())
			{
				if (p != me)
				{
					restart(p);
				}
			}
		}
	}

	private void restart(Actor actor)
	{
		int a = actor.getAnimation(), f = actor.getAnimationFrame();
		Long was = lastFrames.put(actor, ((long) a << 32) | (f & 0xffffffffL));
		if (was == null || a == -1 || (int) (was >> 32) != a)
		{
			return;
		}
		int before = (int) (long) was;
		if (f >= before || f > 1)
		{
			return;
		}
		Animation anim = client.loadAnimation(a);
		int last = anim == null ? Integer.MAX_VALUE : anim.isMayaAnim() ? anim.getDuration() - 1 : anim.getNumFrames() - 1;
		if (isRestart(before, f, last))
		{
			JsonObject line = emit("anim");
			line.add("who", EncounterSnap.ref(client, actor));
			line.addProperty("a", a);
			line.addProperty("o", actor.getCurrentOrientation());
			EncounterSnap.actorTile(line, actor);
			line.addProperty("restart", true);
		}
	}

	/** Whether an animation's frame going from {@code before} to {@code now} (the same animation, the next cycle) is a
	 *  restart: back near its start from short of its last frame ({@code last}), where a loop wraps only from its last. */
	static boolean isRestart(int before, int now, int last)
	{
		return now < before && now <= 1 && before < last;
	}

	/**
	 * Objects whose animation changed since the last look (Outside's obj_anim lines): the scene within OBJ_RADIUS
	 * tiles, each object drawn by a DynamicObject other than the one last seen (the client makes a new one for each
	 * animation the server sends it). {@code write}: lines written, else only noted (the starting state).
	 */
	private void scanObjects(boolean write)
	{
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (me == null || wv == null)
		{
			return;
		}
		LocalPoint at = me.getLocalLocation();
		if (at == null || at.getWorldView() != wv.getId())
		{
			at = OutsidePlugin.onMainWorld(wv, at);
		}
		if (at == null)
		{
			return;
		}
		Tile[][][] tiles = wv.getScene().getTiles();
		int cx = at.getSceneX(), cy = at.getSceneY();
		Set<Long> seen = new HashSet<>();
		for (int z = 0; z < tiles.length; z++)
		{
			for (int x = Math.max(0, cx - OBJ_RADIUS); x <= Math.min(tiles[z].length - 1, cx + OBJ_RADIUS); x++)
			{
				for (int y = Math.max(0, cy - OBJ_RADIUS); y <= Math.min(tiles[z][x].length - 1, cy + OBJ_RADIUS); y++)
				{
					Tile tile = tiles[z][x][y];
					if (tile == null)
					{
						continue;
					}
					for (GameObject obj : tile.getGameObjects())
					{
						if (obj != null && obj.getSceneMinLocation().equals(tile.getSceneLocation()))
						{
							objectAnim(obj, write, seen);
						}
					}
					objectAnim(tile.getWallObject(), write, seen);
					objectAnim(tile.getDecorativeObject(), write, seen);
					objectAnim(tile.getGroundObject(), write, seen);
				}
			}
		}
		animated.keySet().retainAll(seen);
	}

	/** An object's key among those watched: its hash (where it is and what) and its floor */
	private static long objectKey(TileObject obj)
	{
		return (obj.getHash() << 2) ^ obj.getPlane();
	}

	private void objectAnim(TileObject obj, boolean write, Set<Long> seen)
	{
		if (obj == null)
		{
			return;
		}
		Renderable r = EncounterSnap.renderable(obj);
		if (!(r instanceof DynamicObject))
		{
			return;
		}
		long key = objectKey(obj);
		seen.add(key);
		Renderable was = animated.put(key, r);
		if (!write || was == r || spawnedThisTick.contains(key))
		{
			return;
		}
		int anim = EncounterSnap.animation(r);
		if (anim == -1)
		{
			return;
		}
		JsonObject line = emit("obj_anim");
		line.addProperty("id", obj.getId());
		line.addProperty("kind", EncounterSnap.kind(obj));
		line.addProperty("anim", anim);
		EncounterSnap.tile(line, obj.getWorldView(), obj.getLocalLocation(), obj.getPlane());
		line.addProperty("pl", obj.getPlane());
	}

	// ---- his tick lines

	/**
	 * Writes an actor's stand, walk, run and turn animations when they first appear and whenever they change
	 */
	private void moves(Actor actor)
	{
		JsonArray set = EncounterSnap.moveSet(actor);
		Integer hash = set.hashCode();
		if (!hash.equals(moveSets.put(actor, hash)))
		{
			JsonObject line = emit("moves");
			line.add("who", EncounterSnap.ref(client, actor));
			line.add("anims", set);
		}
	}

	private JsonObject self(Player me)
	{
		JsonObject m = EncounterSnap.actor(client, me);
		m.addProperty("hpNow", client.getBoostedSkillLevel(Skill.HITPOINTS));
		m.addProperty("hpMax", client.getRealSkillLevel(Skill.HITPOINTS));
		m.addProperty("prayNow", client.getBoostedSkillLevel(Skill.PRAYER));
		m.addProperty("prayMax", client.getRealSkillLevel(Skill.PRAYER));
		// Both are stored by the game in tenths or hundredths: 10000 run energy is 100%, 1000 spec is 100%
		m.addProperty("run", client.getEnergy());
		m.addProperty("spec", client.getVarpValue(VarPlayerID.SA_ENERGY));
		JsonArray prayers = new JsonArray();
		for (Prayer prayer : Prayer.values())
		{
			if (client.getVarbitValue(prayer.getVarbit()) == 1)
			{
				prayers.add(prayer.name());
			}
		}
		m.add("prayers", prayers);
		LocalPoint destination = client.getLocalDestinationLocation();
		if (destination != null)
		{
			JsonObject dest = new JsonObject();
			EncounterSnap.tile(dest, client.getTopLevelWorldView(), destination);
			m.add("dest", dest);
		}
		return m;
	}

