	/** What the player chose to open or loot (an object's or an NPC's menu option): kept, never written, so the loot line
	 *  can say where its loot came from; and the inventory as it was, for a corpse's loot. */
	@Subscribe
	public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
	{
		if (recording == null)
		{
			// (the way into a run clicked: armed for the map of its instance; round six)
			net.runelite.api.MenuAction act = event.getMenuAction();
			Run r = act != null && act.name().startsWith("GAME_OBJECT_")
				? runEntered(event.getId(), Text.removeTags(event.getMenuOption() == null ? "" : event.getMenuOption())) : null;
			if (r != null)
			{
				armed = r;
				armedAt = tickNow;
			}
			return;
		}
		String option = Text.removeTags(event.getMenuOption() == null ? "" : event.getMenuOption());
		// (the player's next action lets a chat line's picture go; round five)
		shotsActed();
		// (which kind of click and where in the scene, for the replay's click crosses; round five)
		mark(event);
		// (a delve: the burrow's Leave, after the claim, ends it a few ticks on (Jace, 11/21/2026: "it should only end when
		// the player dies or after they claim their loot and press the leave button on the burrow"); the Mokha Loot
		// Tracker reads the same option; round four)
		if (delve && "Leave".equals(option)
			&& ((event.getParam1() >>> 16) == InterfaceID.DOM_END_LEVEL_UI || delveClaimed))
		{
			delveLeave = whole();
			if (automatic)
			{
				endAt = whole() + LOOT_AFTER;
				endWhy = delveClaimed ? "claimed" : "left";
			}
			return;
		}
		// (Araxxor's corpse: Destroy, for a better chance at the pet and no loot (the wiki: "Harvest, Destroy", a prompt
		// after); kept till the corpse goes; round four)
		NPC on = event.getMenuEntry() == null ? null : event.getMenuEntry().getNpc();
		if (FORFEIT_OPTIONS.contains(option) && on != null && scene != null && scene.killed() && raidArea() == null)
		{
			destroyIndex = on.getIndex();
			destroyTick = whole();
			destroyId = on.getId();
			destroyName = on.getName() == null ? null : Text.removeTags(on.getName());
			invAtDestroy = counts(client.getItemContainer(InventoryID.INV));
			clickedAt = on.getLocalLocation();
			clickedPlane = client.getTopLevelWorldView().getPlane();
			clickedId = on.getId();
			clickedIndex = on.getIndex();
			clickedKind = "npc";
			clickedName = destroyName;
			clickedOption = option;
			clickedTick = whole();
			return;
		}
		if (!LOOT_OPTIONS.contains(option))
		{
			return;
		}
		clickedOption = option;
		if (on != null && on.getIndex() == destroyIndex)
		{
			// (Destroy's prompt answered no, and harvested after all)
			destroyIndex = -1;
		}
		WorldView wv = client.getTopLevelWorldView();
		net.runelite.api.MenuAction a = event.getMenuAction();
		NPC npc = event.getMenuEntry() == null ? null : event.getMenuEntry().getNpc();
		if (npc != null)
		{
			clickedAt = npc.getLocalLocation();
			clickedPlane = wv.getPlane();
			clickedId = npc.getId();
			clickedIndex = npc.getIndex();
			clickedKind = "npc";
			clickedName = npc.getName() == null ? null : Text.removeTags(npc.getName());
		}
		else if (a != null && a.name().startsWith("GAME_OBJECT_"))
		{
			clickedAt = LocalPoint.fromScene(event.getParam0(), event.getParam1(), wv);
			clickedPlane = wv.getPlane();
			clickedId = event.getId();
			clickedIndex = -1;
			clickedKind = "obj";
			net.runelite.api.ObjectComposition def = client.getObjectDefinition(event.getId());
			if (def != null && def.getImpostorIds() != null)
			{
				net.runelite.api.ObjectComposition imp = def.getImpostor();
				def = imp != null ? imp : def;
			}
			clickedName = def == null ? null : Text.removeTags(def.getName());
		}
		else
		{
			return;
		}
		clickedTick = whole();
		invBefore = counts(client.getItemContainer(InventoryID.INV));
	}

	/** A container's items, [id, quantity] each, the empty slots left out. */
	static List<int[]> itemsOf(ItemContainer c)
	{
		List<int[]> out = new ArrayList<>();
		if (c == null)
		{
			return out;
		}
		for (Item item : c.getItems())
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
			{
				out.add(new int[]{item.getId(), item.getQuantity()});
			}
		}
		return out;
	}

	/** A container's count of each item (stacks and slots added up). */
	static Map<Integer, Long> counts(ItemContainer c)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int[] it : itemsOf(c))
		{
			m.merge(it[0], (long) it[1], Long::sum);
		}
		return m;
	}

	/** What an inventory gained over what it had (each item's count up), in the order of {@code now}'s slots. */
	static List<int[]> gained(Map<Integer, Long> before, List<int[]> now)
	{
		Map<Integer, Long> after = new java.util.LinkedHashMap<>();
		for (int[] it : now)
		{
			after.merge(it[0], (long) it[1], Long::sum);
		}
		List<int[]> out = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : after.entrySet())
		{
			long up = e.getValue() - before.getOrDefault(e.getKey(), 0L);
			if (up > 0)
			{
				out.add(new int[]{e.getKey(), (int) Math.min(Integer.MAX_VALUE, up)});
			}
		}
		return out;
	}

	/** The inventory changed: after a click on a corpse (an NPC's loot option, a kill this recording, outside a raid),
	 *  what it gained is the corpse's loot (Jace, 11/21/2026: Araxxor's, the Maggot King's: "the loot goes into the
	 *  inventory"; the ground only when it's full, and that's the item lines). */
	private void corpseLoot(ItemContainer inv)
	{
		if (!"npc".equals(clickedKind) || FORFEIT_OPTIONS.contains(clickedOption) || whole() - clickedTick > CORPSE_TAKE
			|| looted.contains("corpse") || scene == null
			|| !scene.killed() || raidArea() != null)
		{
			return;
		}
		List<int[]> got = gained(invBefore, itemsOf(inv));
		if (!got.isEmpty())
		{
			loot("corpse", got, -1, true);
		}
	}

	/** The inventory changed in a Gauntlet run: after a click on its reward chest, what it gained is the run's loot, as a
	 *  corpse's is (no window: the inventory's own lines, and the moment's plain panel titled with the run's name). The
	 *  extra items the game drops when the inventory's short of room are the item lines, as ever. Round six. */
	private void gauntletChest(ItemContainer inv)
	{
		if (run == null || !run.gauntlet || !"obj".equals(clickedKind) || !GAUNTLET_CHESTS.contains(clickedId)
			|| whole() - clickedTick > CORPSE_TAKE || looted.contains(run.name))
		{
			return;
		}
		List<int[]> got = gained(invBefore, itemsOf(inv));
		if (!got.isEmpty())
		{
			loot(run.name, got, -1, "inventory");
		}
	}

	/** Whether a kill's corpse is still there to loot (an NPC of the killed one's name near them, with a loot option and
	 *  no Attack), so the recording waits for it, CORPSE_WAIT ticks at most. */
	private boolean corpseWaiting()
	{
		if (scene == null || !scene.killed() || whole() >= scene.killTick() + CORPSE_WAIT)
		{
			return false;
		}
		Player me = client.getLocalPlayer();
		String killed = scene.killNpc();
		if (me == null || killed == null)
		{
			return false;
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			net.runelite.api.NPCComposition def = npc.getTransformedComposition();
			String name = npc.getName() == null ? "" : Text.removeTags(npc.getName());
			// (the killed one's name, or one fought: the Royal Titans' count line names neither titan, and each falls
			// where it stood with its own name, Branda the Fire Queen's and Eldric the Ice King's; round four)
			// (or its corpse by name: "Maggot King Corpse", 11/22/2026)
			if (def == null || !(name.equalsIgnoreCase(killed) || name.equalsIgnoreCase(killed + " Corpse") || scene.fought(name))
				|| npc.getWorldLocation().distanceTo(me.getWorldLocation()) > 15)
			{
				continue;
			}
			boolean loot = false, attack = false;
			for (String act : def.getActions())
			{
				if (act != null)
				{
					loot |= LOOT_OPTIONS.contains(Text.removeTags(act));
					attack |= "Attack".equals(Text.removeTags(act));
				}
			}
			if (loot && !attack)
			{
				corpseOf = name;
				return true;
			}
		}
		return false;
	}

	/**
	 * A loot line (Outside's own kind, round three): where it came from (the chest or corpse the player last chose to
	 * open or loot, within 30 ticks; else the nearest thing named a chest within 10 tiles; else the player), the source
	 * ("Chambers of Xeric", "Lunar Chest", "corpse"), the window it came in, and each item with its GE price and high
	 * alchemy value, each. Once a source a recording; the scene moment's anchor; a boss outside a raid ends a few ticks
	 * on.
	 */
	private void loot(String source, List<int[]> items, int window, boolean corpse)
	{
		loot(source, items, window, corpse ? "inventory" : "reward");
	}

	/** {@code kind}: "reward", "inventory" (a corpse looted), "destroyed" (a corpse destroyed: no window, no picture). */
	private void loot(String source, List<int[]> items, int window, String kind)
	{
		boolean corpse = !"reward".equals(kind);
		if (!looted.add(source))
		{
			return;
		}
		if (waitingFor != null && source.equals(waitingFor.source))
		{
			waitingFor = null;
		}
		WorldView wv = client.getTopLevelWorldView();
		Player me = client.getLocalPlayer();
		for (int[] it : items)
		{
			defineItem(it[0]);
		}
		JsonObject line = emit("loot");
		line.addProperty("source", source);
		LocalPoint at = null;
		int plane = wv.getPlane();
		JsonObject from = null;
		if (clickedAt != null && whole() - clickedTick <= 30)
		{
			at = clickedAt;
			plane = clickedPlane;
			from = new JsonObject();
			from.addProperty("kind", clickedKind);
			from.addProperty("id", clickedId);
			if (clickedName != null)
			{
				from.addProperty("name", clickedName);
			}
		}
		else
		{
			Object[] near = nearestChest(wv, me);
			if (near != null)
			{
				at = (LocalPoint) near[0];
				from = (JsonObject) near[1];
			}
		}
		if (at == null && me != null)
		{
			at = me.getLocalLocation();
		}
		EncounterSnap.tile(line, wv, at, plane);
		// (the Gauntlet's chest: a chest whose loot goes into the inventory, "into": "inventory", titled by the run, as a
		// chest's window titles it; round six)
		boolean runChest = corpse && run != null && run.name.equals(source);
		line.addProperty("at", from != null ? (corpse && !runChest ? "corpse" : "chest") : "player");
		if (runChest)
		{
			line.addProperty("into", "inventory");
			line.addProperty("title", source);
		}
		// (a corpse's: what the player chose, "harvest" or "destroy" (Araxxor's), "loot"...; round four)
		else if (corpse && clickedOption != null)
		{
			line.addProperty("choice", clickedOption.toLowerCase(java.util.Locale.ROOT));
		}
		if (from != null)
		{
			line.add("from", from);
		}
		if (window >= 0)
		{
			line.addProperty("window", window);
			String title = windowTitle(window);
			if (title != null)
			{
				line.addProperty("title", title);
			}
		}
		JsonArray list = new JsonArray();
		List<EncounterScene.Loot> scened = new ArrayList<>();
		for (int[] it : items)
		{
			long[] p = host.prices(it[0]);
			JsonObject o = new JsonObject();
			o.addProperty("id", it[0]);
			o.addProperty("qty", it[1]);
			o.addProperty("ge", p == null ? 0 : p[0]);
			o.addProperty("ha", p == null ? 0 : p[1]);
			list.add(o);
			ItemComposition def = client.getItemDefinition(it[0]);
			scened.add(new EncounterScene.Loot(it[0], it[1], p == null ? 0 : p[0], p == null ? 0 : p[1],
				def == null ? null : Text.removeTags(def.getName())));
		}
		line.add("items", list);
		// (the scene moment: the chest's opening, the window as the player saw it laid over)
		EncounterScene.Window w = null;
		if (scene != null)
		{
			w = new EncounterScene.Window(kind, source, window,
				window >= 0 ? windowTitle(window) : "destroyed".equals(kind) ? clickedOption : runChest ? source : null, scened);
			scene.loot(whole(), w, at, plane);
		}
		// (its picture a few client cycles on, once the window's laid out and drawn with its items, for its `window` line
		// and the moment both. Doom's claim is a picture of the burrow's window again. None for a corpse: Jace, 11/21/2026,
		// round five, of the inventory's crop popping in and out, "I just want to make sure the loot and inventory windows
		// look clean and true to the game": the replay shows the inventory itself from its `items` lines, and the moment
		// the items gained as a plain panel in the game's colours)
		if (!corpse)
		{
			boolean burrow = window == InterfaceID.DOM_END_LEVEL_UI;
			shoot(burrow ? "burrow" : "chest", window, window >= 0 ? windowTitle(window) : null, items, -1, burrow, w);
		}
		// (a boss outside a raid: ends a few ticks after its loot; a raid goes on to its treasure room's door)
		boolean raid = raidArea() != null;
		for (Chest c : CHESTS)
		{
			raid |= c.raid && c.source.equals(source);
		}
		// (a delve's claim: it goes on to the burrow's Leave; round four)
		if (DOOM.equals(source))
		{
			delveClaimed = true;
		}
		if (automatic && run == COLOSSEUM && COLOSSEUM.name.equals(source))
		{
			// (the Colosseum's claim: noted, nothing ended; the run ends when the player leaves the arena, "claimed"
			// (runEnding). 11/21/2026, Jace: "it should end when you leave the arena")
		}
		else if (automatic && !raid && !delve)
		{
			endAt = Math.max(endAt, whole() + LOOT_AFTER);
			if (endWhy == null)
			{
				endWhy = "looted";
			}
		}
	}

	// ---- the windows as they appear (11/21/2026, round five; ghillie's claude/outstation.md, "Encounters, round five";
	// Jace: "I'd like if the replay showed loot too for each level, just as the replay shows the loot for the chest at the
	// end of the raid"). Each reward-type window, as the player's client drew it, is a `window` line the replay lays over
	// its view at that tick: a raid's or a boss's reward chest (every time it opens), Doom's burrow at every level and its
	// claim, the pet's chat line (a corpse's loot is the inventory's own `items` lines: no crop of it, Jace's ask). The picture is a PNG of the window's box
	// on the canvas only (RuneLite's DrawManager, the next frame once it's laid out, as round three's), base64 in the line;
	// the same capture is the moment's picture. A `window_close` line, naming it by its number, when it goes: its interface
	// closed, a newer picture of the same window, or (a chat line) the player's next action, CLOSE_LEAST to
	// CLOSE_MOST ticks on. Nothing but what the player's own screen showed: no clicks, no layout of anything else.

	/** a chat line's or the inventory's picture: kept at least this many ticks, gone at the next action after, and by the
	 *  most whatever comes */
	static final int CLOSE_LEAST = 2, CLOSE_MOST = 10;
	/** client cycles after it's asked for before a picture that hasn't come is given up (its line goes without one) */
	static final int SHOT_WAIT = 50;

	/** A window being taken, and once written, open till its `window_close`. */
	static final class Shot
	{
		final String kind;
		final int group, n, inv;
		final boolean claim;
		final EncounterScene.Window moment;
		volatile String title;
		List<int[]> items;
		int in = 3, tries, waited, closeBy = -1, openedAt;
		boolean asked, closed;
		volatile byte[] png;
		java.awt.Rectangle box;
		int cw, ch;

		Shot(String kind, int group, int n, String title, List<int[]> items, int inv, boolean claim, EncounterScene.Window moment)
		{
			this.kind = kind;
			this.group = group;
			this.n = n;
			this.title = title;
			this.items = items;
			this.inv = inv;
			this.claim = claim;
			this.moment = moment;
			// (a chat row waits for the chatbox to draw it; a chest's inventory can fill a tick or two after its window)
			this.tries = "chat".equals(kind) ? 12 : 60;
			// (a window waits about a second before its picture: the Fractured Archive's chest came up as the scene
			// behind it, or its bare background, taken three cycles in; 11/21/2026, round nine, Jace's three raids)
			this.in = group >= 0 ? 50 : 3;
		}

		/** the one window it stands for: another picture of it replaces this one */
		String place()
		{
			return group >= 0 ? "g" + group : kind;
		}
	}

	/**
	 * A picture as a PNG, as small as it goes without changing a pixel (round five: every window's picture is in the
	 * recording now): the game's interfaces are drawn from few colours, so one of 256 colours or fewer is written with a
	 * palette (8 bits a pixel or fewer) when that's the smaller, and one with more as it is (24 bits). Lossless either way.
	 */
	static byte[] png(java.awt.image.BufferedImage img) throws java.io.IOException
	{
		int w = img.getWidth(), h = img.getHeight();
		int[] px = img.getRGB(0, 0, w, h, null, 0, w);
		Map<Integer, Integer> colours = new java.util.LinkedHashMap<>();
		for (int p : px)
		{
			int rgb = p & 0xffffff;
			if (!colours.containsKey(rgb))
			{
				if (colours.size() == 256)
				{
					colours = null;
					break;
				}
				colours.put(rgb, colours.size());
			}
		}
		java.awt.image.BufferedImage out = img;
		if (colours != null)
		{
			int n = Math.max(2, colours.size());
			byte[] r = new byte[n], g = new byte[n], b = new byte[n];
			for (Map.Entry<Integer, Integer> e : colours.entrySet())
			{
				int c = e.getKey(), i = e.getValue();
				r[i] = (byte) (c >> 16);
				g[i] = (byte) (c >> 8);
				b[i] = (byte) c;
			}
			int bits = n <= 2 ? 1 : n <= 4 ? 2 : n <= 16 ? 4 : 8;
			java.awt.image.IndexColorModel cm = new java.awt.image.IndexColorModel(bits, n, r, g, b);
			out = new java.awt.image.BufferedImage(w, h, bits == 8 ? java.awt.image.BufferedImage.TYPE_BYTE_INDEXED
				: java.awt.image.BufferedImage.TYPE_BYTE_BINARY, cm);
			java.awt.image.WritableRaster ras = out.getRaster();
			for (int y = 0; y < h; y++)
			{
				for (int x = 0; x < w; x++)
				{
					ras.setSample(x, y, 0, colours.get(px[y * w + x] & 0xffffff));
				}
			}
		}
		java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
		javax.imageio.ImageIO.write(out, "png", bytes);
		if (out != img)
		{
			// (the smaller of the two: a picture that repeats can pack smaller in 24 bits)
			java.io.ByteArrayOutputStream plain = new java.io.ByteArrayOutputStream();
			javax.imageio.ImageIO.write(img, "png", plain);
			if (plain.size() < bytes.size())
			{
				return plain.toByteArray();
			}
		}
		return bytes.toByteArray();
	}

	/** A window to take: {@code group} its interface (-1: the inventory's crop, the chat line), {@code items} what's in it
	 *  (null: read from {@code inv} once it's drawn), {@code moment} the moment's window the same picture is for. */
	private void shoot(String kind, int group, String title, List<int[]> items, int inv, boolean claim, EncounterScene.Window moment)
	{
		if (recording == null)
		{
			return;
		}
		Shot s = new Shot(kind, group, ++shotNo, title, items, inv, claim, moment);
		for (Shot o : new ArrayList<>(shots))
		{
			if (o.place().equals(s.place()))
			{
				shotClose(o);
			}
		}
		for (Shot o : new ArrayList<>(shown))
		{
			if (o.place().equals(s.place()))
			{
				shotClose(o);
			}
		}
		shots.add(s);
	}

	/** Each client cycle: each window due taken from the next frame (its box, its title and items as they stand now), and
	 *  each whose picture has come written. */
	private void shotsCycle()
	{
		for (java.util.Iterator<Shot> it = shots.iterator(); it.hasNext(); )
		{
			Shot s = it.next();
			if (s.asked)
			{
				if (++s.waited > SHOT_WAIT)
				{
					it.remove();
					shotWritten(s);
				}
				continue;
			}
			if (--s.in > 0)
			{
				continue;
			}
			if (s.group >= 0)
			{
				String t = windowTitle(s.group);
				if (t != null)
				{
					s.title = t;
				}
			}
			java.awt.Rectangle b = "chat".equals(s.kind) ? chatLineBounds(s.title) : s.group >= 0 ? windowBounds(s.group) : inventoryBounds();
			List<int[]> got = s.items != null ? s.items : itemsOf(client.getItemContainer(s.inv));
			boolean ready = b != null && b.width > 0 && b.height > 0 && (s.items != null || !got.isEmpty());
			if (!ready && --s.tries > 0)
			{
				s.in = 2;
				continue;
			}
			s.items = got;
			if (b == null || b.width <= 0 || b.height <= 0)
			{
				// (never drawn where it could be found: written without its picture)
				it.remove();
				shotWritten(s);
				continue;
			}
			s.asked = true;
			s.box = new java.awt.Rectangle(b);
			s.cw = client.getCanvasWidth();
			s.ch = client.getCanvasHeight();
			host.picture(b, png ->
			{
				s.png = png;
				if (s.moment != null)
				{
					s.moment.pw = b.width;
					s.moment.ph = b.height;
					s.moment.picture = png;
				}
				shotsTaken.add(s);
			});
		}
		for (Shot s; (s = shotsTaken.poll()) != null; )
		{
			if (shots.remove(s))
			{
				shotWritten(s);
			}
		}
	}

	/** A window's `window` line: what it is, its items with their prices, where it was on the canvas, its picture. */
	private void shotWritten(Shot s)
	{
		if (recording == null)
		{
			return;
		}
		JsonObject line = emit("window");
		line.addProperty("n", s.n);
		line.addProperty("kind", s.kind);
		if (s.group >= 0)
		{
			line.addProperty("group", s.group);
		}
		if (s.title != null)
		{
			line.addProperty("title", s.title);
		}
		JsonArray list = new JsonArray();
		for (int[] it : s.items == null ? Collections.<int[]>emptyList() : s.items)
		{
			defineItem(it[0]);
			long[] p = host.prices(it[0]);
			JsonObject o = new JsonObject();
			o.addProperty("id", it[0]);
			o.addProperty("qty", it[1]);
			o.addProperty("ge", p == null ? 0 : p[0]);
			o.addProperty("ha", p == null ? 0 : p[1]);
			list.add(o);
		}
		line.add("items", list);
		if (s.claim)
		{
			line.addProperty("claim", true);
		}
		if (s.box != null)
		{
			JsonArray box = new JsonArray();
			box.add(s.box.x);
			box.add(s.box.y);
			box.add(s.box.width);
			box.add(s.box.height);
			line.add("box", box);
			JsonArray canvas = new JsonArray();
			canvas.add(s.cw);
			canvas.add(s.ch);
			line.add("canvas", canvas);
		}
		byte[] png = s.png;
		if (png != null && png.length > 0 && png.length <= EncounterScene.PICTURE_MOST)
		{
			line.addProperty("picture", java.util.Base64.getEncoder().encodeToString(png));
		}
		s.openedAt = whole();
		if (s.group < 0)
		{
			s.closeBy = whole() + CLOSE_MOST;
		}
		if (s.closed)
		{
			emit("window_close").addProperty("n", s.n);
			return;
		}
		shown.add(s);
	}

	/** A window gone: its `window_close` (one not written yet goes as soon as it is, then closes). */
	private void shotClose(Shot s)
	{
		if (shown.remove(s))
		{
			JsonObject line = emit("window_close");
			line.addProperty("n", s.n);
			return;
		}
		s.closed = true;
	}

	/** An interface closed: its windows' pictures with it. */
	private void shotsClosed(int group)
	{
		for (Shot s : new ArrayList<>(shown))
		{
			if (s.group == group)
			{
				shotClose(s);
			}
		}
		for (Shot s : shots)
		{
			if (s.group == group)
			{
				s.closed = true;
			}
		}
	}

	/** The player's next action: a chat line's or the inventory's picture goes (once it's been up CLOSE_LEAST ticks). */
	private void shotsActed()
	{
		for (Shot s : shown)
		{
			if (s.group < 0)
			{
				s.closeBy = Math.min(s.closeBy, Math.max(whole(), s.openedAt + CLOSE_LEAST));
			}
		}
	}

	/** Each tick: a chat line's or the inventory's picture past its time closed. */
	private void shotsExpire()
	{
		for (Shot s : new ArrayList<>(shown))
		{
			if (s.group < 0 && s.closeBy >= 0 && whole() >= s.closeBy)
			{
				shotClose(s);
			}
		}
	}

	// ---- the click crosses (11/21/2026, round five; Jace: click markers in the replay, "pink or lime, just as we use for
	// our left click animations on the website"). A `mark` line for each click the game answers with its cross: "walk"
	// (the game's yellow cross) with the scene tile walked to, or "act" (its red cross: an NPC, a player, an object or an
	// item on the ground, attacked, talked to, taken, used on) with who (by index, never a name) or the object's tile.
	// Never where the cursor was on the screen, never the option's text: only the kind of click and its place in the
	// scene. Not in the Wilderness or on PvP worlds, as nothing is.

	/** The menu actions that answer with the red cross: an option on an NPC, a player, an object or a ground item, or
	 *  something used or cast on one (RuneLite's MenuAction names). */
	static String markKind(String action)
	{
		if (action == null)
		{
			return null;
		}
		if ("WALK".equals(action))
		{
			return "walk";
		}
		if (action.startsWith("NPC_") && action.contains("_OPTION") || action.startsWith("PLAYER_") && action.contains("_OPTION")
			|| action.startsWith("GAME_OBJECT_") && action.contains("_OPTION") || action.startsWith("GROUND_ITEM_") && action.contains("_OPTION")
			|| action.startsWith("WIDGET_TARGET_ON_") && !"WIDGET_TARGET_ON_WIDGET".equals(action))
		{
			return "act";
		}
		return null;
	}

	private void mark(net.runelite.api.events.MenuOptionClicked event)
	{
		net.runelite.api.MenuAction a = event.getMenuAction();
		String kind = markKind(a == null ? null : a.name());
		if (kind == null || bankPinShowing())
		{
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		net.runelite.api.MenuEntry entry = event.getMenuEntry();
		NPC npc = entry == null ? null : entry.getNpc();
		Player player = entry == null ? null : entry.getPlayer();
		JsonObject line;
		if ("walk".equals(kind))
		{
			Tile t = wv.getSelectedSceneTile();
			if (t == null)
			{
				return;
			}
			line = emit("mark");
			line.addProperty("kind", kind);
			EncounterSnap.tile(line, wv, t.getLocalLocation(), wv.getPlane());
			return;
		}
		line = emit("mark");
		line.addProperty("kind", kind);
		if (npc != null || player != null)
		{
			line.add("target", EncounterSnap.ref(client, npc != null ? npc : player));
		}
		else
		{
			EncounterSnap.tile(line, wv, LocalPoint.fromScene(event.getParam0(), event.getParam1(), wv), wv.getPlane());
		}
	}

	/** The nearest object or NPC named a chest (or its corpse, or Doom's burrow) within 10 tiles: {its tile, {kind, id, name}}, or null. */
	private Object[] nearestChest(WorldView wv, Player me)
	{
		if (me == null || me.getLocalLocation() == null)
		{
			return null;
		}
		LocalPoint mine = me.getLocalLocation();
		Object[] best = null;
		int bestD = 10 * 128 + 1;
		for (NPC npc : wv.npcs())
		{
			String name = npc.getName() == null ? "" : Text.removeTags(npc.getName());
			LocalPoint lp = npc.getLocalLocation();
			int d = lp == null ? Integer.MAX_VALUE : Math.max(Math.abs(lp.getX() - mine.getX()), Math.abs(lp.getY() - mine.getY()));
			if (name.toLowerCase().contains("chest") && d < bestD)
			{
				JsonObject f = new JsonObject();
				f.addProperty("kind", "npc");
				f.addProperty("id", npc.getId());
				f.addProperty("name", name);
				best = new Object[]{lp, f};
				bestD = d;
			}
		}
		Tile[][][] tiles = wv.getScene().getTiles();
		int plane = wv.getPlane(), cx = mine.getSceneX(), cy = mine.getSceneY();
		for (int x = Math.max(0, cx - 10); x <= Math.min(tiles[plane].length - 1, cx + 10); x++)
		{
			for (int y = Math.max(0, cy - 10); y <= Math.min(tiles[plane][x].length - 1, cy + 10); y++)
			{
				Tile tile = tiles[plane][x][y];
				if (tile == null)
				{
					continue;
				}
				for (GameObject o : tile.getGameObjects())
				{
					if (o == null || !tile.getSceneLocation().equals(o.getSceneMinLocation()))
					{
						continue;
					}
					net.runelite.api.ObjectComposition def = client.getObjectDefinition(o.getId());
					if (def != null && def.getImpostorIds() != null && def.getImpostor() != null)
					{
						def = def.getImpostor();
					}
					String name = def == null || def.getName() == null ? "" : Text.removeTags(def.getName());
					LocalPoint lp = o.getLocalLocation();
					int d = Math.max(Math.abs(lp.getX() - mine.getX()), Math.abs(lp.getY() - mine.getY()));
					// (round four: Doom of Mokhaiotl's "Burrow hole", its pile's place)
					String lower = name.toLowerCase();
					if ((lower.contains("chest") || lower.contains("coffer") || lower.contains("burrow")) && d < bestD)
					{
						JsonObject f = new JsonObject();
						f.addProperty("kind", "obj");
						f.addProperty("id", o.getId());
						f.addProperty("name", name);
						best = new Object[]{lp, f};
						bestD = d;
					}
				}
			}
		}
		return best;
	}

	/** A window's title as the game draws it: the first text in it that has a letter (its static parts in order, then
	 *  their children), or null. */
	private String windowTitle(int group)
	{
		for (int i = 0; i < 128; i++)
		{
			Widget w = client.getWidget(group, i);
			if (w == null)
			{
				continue;
			}
			String t = w.getText() == null ? "" : Text.removeTags(w.getText()).trim();
			if (!t.isEmpty() && t.matches("(?s).*[A-Za-z].*"))
			{
				return t;
			}
			Widget[] kids = w.getDynamicChildren();
			for (int k = 0; kids != null && k < kids.length; k++)
			{
				String kt = kids[k] == null || kids[k].getText() == null ? "" : Text.removeTags(kids[k].getText()).trim();
				if (!kt.isEmpty() && kt.matches("(?s).*[A-Za-z].*"))
				{
					return kt;
				}
			}
		}
		return null;
	}

	/** Where a window is drawn on the canvas: its first part's box (the window's frame), else all its shown parts'.
	 *  (Round five, 11/21/2026: a window whose first part is a layer over the whole game view, as Doom's burrow (919) is,
	 *  its frame 512 by 334 with the scene showing through, is the union of what it draws instead: its texts, sprites,
	 *  items and filled boxes, each part and its children, leaving out layers and anything near the layer's own size, so
	 *  the picture is the window and not the scene behind it.) */
	private java.awt.Rectangle windowBounds(int group)
	{
		if (group < 0)
		{
			return null;
		}
		java.awt.Rectangle all = null;
		int cw = client.getCanvasWidth(), ch = client.getCanvasHeight();
		java.awt.Rectangle canvas = new java.awt.Rectangle(0, 0, cw, ch);
		Widget root = client.getWidget(group, 0);
		java.awt.Rectangle rb = root == null || root.isHidden() ? null : root.getBounds();
		boolean overView = rb != null && root.getType() == net.runelite.api.widgets.WidgetType.LAYER
			&& rb.width * rb.height >= cw * ch / 3;
		if (rb != null && !overView && rb.width >= 120 && rb.height >= 80 && rb.width < cw && rb.height < ch)
		{
			return rb.intersection(canvas);
		}
		for (int i = 0; i < 128; i++)
		{
			Widget w = client.getWidget(group, i);
			if (w == null || w.isHidden())
			{
				continue;
			}
			if (!overView)
			{
				java.awt.Rectangle b = w.getBounds();
				if (b != null && b.width > 0 && b.height > 0)
				{
					all = all == null ? new java.awt.Rectangle(b) : all.union(b);
				}
				continue;
			}
			all = drawnIn(w, rb, all, 0);
		}
		return all == null ? null : all.intersection(canvas);
	}

	/** The union of what a part and its children draw (texts, sprites, items, models, filled boxes), leaving out layers
	 *  and anything near {@code over}'s size (a layer over the whole view, round five). */
	private static java.awt.Rectangle drawnIn(Widget w, java.awt.Rectangle over, java.awt.Rectangle all, int depth)
	{
		if (w == null || w.isHidden() || depth > 6)
		{
			return all;
		}
		java.awt.Rectangle b = w.getBounds();
		int type = w.getType();
		boolean big = b != null && b.width * b.height >= over.width * over.height * 0.8;
		boolean draws = type == net.runelite.api.widgets.WidgetType.TEXT && w.getText() != null && !Text.removeTags(w.getText()).trim().isEmpty()
			|| type == net.runelite.api.widgets.WidgetType.GRAPHIC && (w.getSpriteId() >= 0 || w.getItemId() >= 0)
			|| type == net.runelite.api.widgets.WidgetType.MODEL
			|| type == net.runelite.api.widgets.WidgetType.RECTANGLE && w.isFilled() && w.getOpacity() < 255;
		if (draws && !big && b != null && b.width > 0 && b.height > 0)
		{
			all = all == null ? new java.awt.Rectangle(b) : all.union(b);
		}
		for (Widget[] kids : new Widget[][]{w.getDynamicChildren(), w.getStaticChildren(), w.getNestedChildren()})
		{
			for (int k = 0; kids != null && k < kids.length; k++)
			{
				all = drawnIn(kids[k], over, all, depth + 1);
			}
		}
		return all;
	}

	/** The inventory's box on the canvas, when it's showing (a corpse's loot arriving there). */
	private java.awt.Rectangle inventoryBounds()
	{
		Widget w = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (w == null || w.isHidden())
		{
			return null;
		}
		java.awt.Rectangle b = w.getBounds();
		return b == null || b.width <= 0 ? null : b;
	}

	private void containers(ItemContainer container, String which)
	{
		if (container == null)
		{
			return;
		}
		JsonObject line = emit("items");
		line.addProperty("which", which);
		JsonArray items = new JsonArray();
		for (Item item : container.getItems())
		{
			defineItem(item.getId());
			JsonArray pair = new JsonArray();
			pair.add(item.getId());
			pair.add(item.getQuantity());
			items.add(pair);
		}
		line.add("items", items);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (recording == null)
		{
			return;
		}
		JsonObject line = emit("stat");
		line.addProperty("skill", event.getSkill().name());
		line.addProperty("xp", event.getXp());
		line.addProperty("level", event.getLevel());
		line.addProperty("boosted", event.getBoostedLevel());
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		// (the player attacking an open boss area's boss starts one; a recording's boss fought noted: 11/22/2026)
		if (event.getSource() != null && event.getSource() == client.getLocalPlayer() && event.getTarget() instanceof NPC)
		{
			if (recording == null)
			{
				fightOpen((NPC) event.getTarget());
			}
			else
			{
				fought((NPC) event.getTarget());
			}
		}
		if (!wanted(event.getSource()))
		{
			return;
		}
		JsonObject line = emit("target");
		line.add("who", EncounterSnap.ref(client, event.getSource()));
		line.add("at", EncounterSnap.ref(client, event.getTarget()));
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (!wanted(actor))
		{
			return;
		}
		emit("death").add("who", EncounterSnap.ref(client, actor));
		// (the boss they fought dead, count line or not: 11/22/2026)
		if (actor instanceof NPC)
		{
			bossDied((NPC) actor);
		}
		// (the Hunllef falling is a Gauntlet's kill, its count line or not; round six)
		if (run != null && run.gauntlet && actor instanceof NPC && actor.getName() != null
			&& Text.removeTags(actor.getName()).endsWith("Hunllef"))
		{
			runKilled(Text.removeTags(actor.getName()));
		}
		if (scene != null && actor == client.getLocalPlayer())
		{
			scene.died(whole());
		}
		// (a death ends an automatic recording a few ticks on: not in a raid, which goes on)
		if (actor == client.getLocalPlayer() && automatic && endAt < 0 && (area == null || !Presence.RAID.equals(area.kind)))
		{
			endAt = whole() + AFTER_DEATH;
			endWhy = "died";
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKPIN_KEYPAD)
		{
			bankPinOpen = true;
		}
		if (recording != null)
		{
			emit("widget_open").addProperty("group", event.getGroupId());
			rewardWindow(event.getGroupId());
			// (the burrow's window: a delve; round four)
			delve |= event.getGroupId() == InterfaceID.DOM_END_LEVEL_UI;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKPIN_KEYPAD)
		{
			bankPinOpen = false;
		}
		if (recording != null)
		{
			emit("widget_close").addProperty("group", event.getGroupId());
			shotsClosed(event.getGroupId());
		}
	}
}

package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;

/**
 * The goal items (11/17/2026, update 3; Goji Berries: "what if you could set a goal item from the plugin then it shows
 * your kc and dryness on the top of ur profile"): the items a player is after, each added from the game's own item
 * search (the side tab's "Add a goal item", or ::outsidegoal). Since 11/19/2026 more than one (Cranky: "I'd like to have
 * more than 1 goal item. maybe the button would be 'add a goal item' and it would just add to the list, and you'd just
 * have to x any you don't want anymore"; Jace: "choose ONE of the goal items to be displayed as a 3d model, while the
 * rest of the goal items are listed under the first and each other with their dryness bars"): MOST at most, one of them
 * shown (its 3D model on the page), the rest listed under it.
 *
 * Sent to their page's keep as the one shown, {"id", "name", "model"}, with the rest in "more" ({"id", "name"}, no
 * model); a goal the game's collection log line (or the loot) names has {"got": {"at", "counts"}}, the kill and clue
 * counts then (the page reads the kill count it took from those). The page works out how dry they are from the wiki's
 * drop rates.
 *
 * Or none shown as a model (11/19/2026, Jace: "add the option to NOT show a 3D model on your page for your goal/goals
 * list"): every goal listed with its picture, in the order they were added, nothing turning. Since 11/21/2026 (round
 * nine) the first then carries {"nomodel": true}: the page builds a goal's model from the game's own files when one
 * comes without it (an older plugin's goals mostly did), and this tells it they chose none. (A new key rather than
 * "model": false, which the relay before then refused, goal and all; it drops a key it doesn't know.)
 *
 * Kept for the RuneScape profile as one setting, LIST: {"shown": id, "model": false (none turning; left out: one is),
 * "list": [{"id", "got"?, "counts"?}, ...]}, in the order they were added. The one goal kept before (ITEM, GOT,
 * GOT_COUNTS) is read into it once, then let go.
 */
final class Goal
{
	private Goal()
	{
	}

	/** The RuneScape profile's own settings: the list (since 11/19/2026). */
	static final String LIST = "goals";
	/** Before 11/19/2026, the one goal: the item, and when it was got (0: not yet), with the counts then. */
	static final String ITEM = "goalItem";
	static final String GOT = "goalGot";
	static final String GOT_COUNTS = "goalGotCounts";
	/** How many goals at most (the relay takes 20; the page's column fits these). */
	static final int MOST = 10;

	/** One goal: the item, when it was got (0: not yet) and the counts then (null: none kept). */
	static final class One
	{
		final int id;
		long got;
		JsonObject counts;

		One(int id)
		{
			this.id = id;
		}
	}

	/** A player's goals: the list, the one shown (0: none), and whether it's shown as its model (false: none turning). */
	static final class Kept
	{
		final List<One> list = new ArrayList<>();
		int shown;
		boolean model = true;

		One find(int id)
		{
			for (One g : list)
			{
				if (g.id == id)
				{
					return g;
				}
			}
			return null;
		}

		/** The one shown, then the rest in the order they were added (none shown as a model: all in that order). */
		List<One> pageOrder()
		{
			if (!model)
			{
				return new ArrayList<>(list);
			}
			List<One> out = new ArrayList<>();
			One top = find(shown);
			if (top != null)
			{
				out.add(top);
			}
			for (One g : list)
			{
				if (g != top)
				{
					out.add(g);
				}
			}
			return out;
		}

		/** Added at the list's end (the first one added is shown); false when it's there already or the list is full. */
		boolean add(int id)
		{
			if (id <= 0 || find(id) != null || list.size() >= MOST)
			{
				return false;
			}
			list.add(new One(id));
			if (find(shown) == null)
			{
				shown = id;
			}
			return true;
		}

		/** Moved to this place in the list, counted without it (0: the top), as its row's dragged in the side tab
		 *  (11/22/2026, Jace: re-ordering goals, "include goal re-ordering in this update too"); false when it isn't there
		 *  or is there already. The page lists the rest in this order under the one shown. */
		boolean move(int id, int to)
		{
			One g = find(id);
			if (g == null)
			{
				return false;
			}
			int from = list.indexOf(g);
			list.remove(from);
			int at = Math.max(0, Math.min(list.size(), to));
			list.add(at, g);
			return at != from;
		}

		/** Taken off; the one shown taken off, the first left is shown. */
		boolean forget(int id)
		{
			One g = find(id);
			if (g == null)
			{
				return false;
			}
			list.remove(g);
			if (shown == id)
			{
				shown = list.isEmpty() ? 0 : list.get(0).id;
			}
			return true;
		}

		/** This one shown as its model (none was: one is again). */
		boolean show(int id)
		{
			if (find(id) == null || (shown == id && model))
			{
				return false;
			}
			shown = id;
			model = true;
			return true;
		}

		/** None turning as a model: every goal listed with its picture. */
		boolean noModel()
		{
			if (!model)
			{
				return false;
			}
			model = false;
			return true;
		}

		String json(Gson gson)
		{
			JsonObject o = new JsonObject();
			o.addProperty("shown", shown);
			if (!model)
			{
				o.addProperty("model", false);
			}
			JsonArray a = new JsonArray();
			for (One g : list)
			{
				JsonObject e = new JsonObject();
				e.addProperty("id", g.id);
				if (g.got > 0)
				{
					e.addProperty("got", g.got);
					if (g.counts != null)
					{
						e.add("counts", g.counts);
					}
				}
				a.add(e);
			}
			o.add("list", a);
			return gson.toJson(o);
		}

		/** As kept (null or anything broken: none), each item once, MOST at most. */
		static Kept from(String json, Gson gson)
		{
			Kept k = new Kept();
			if (json == null || json.isEmpty())
			{
				return k;
			}
			try
			{
				JsonObject o = gson.fromJson(json, JsonObject.class);
				JsonArray a = o != null && o.has("list") && o.get("list").isJsonArray() ? o.getAsJsonArray("list") : new JsonArray();
				for (JsonElement el : a)
				{
					if (!el.isJsonObject() || !el.getAsJsonObject().has("id"))
					{
						continue;
					}
					JsonObject e = el.getAsJsonObject();
					int id = e.get("id").getAsInt();
					if (!k.add(id))
					{
						continue;
					}
					One g = k.find(id);
					g.got = e.has("got") ? e.get("got").getAsLong() : 0;
					g.counts = g.got > 0 && e.has("counts") && e.get("counts").isJsonObject() ? e.getAsJsonObject("counts") : null;
				}
				int shown = o != null && o.has("shown") ? o.get("shown").getAsInt() : 0;
				if (k.find(shown) != null)
				{
					k.shown = shown;
				}
				k.model = o == null || !o.has("model") || o.get("model").getAsBoolean();
			}
			catch (RuntimeException ex)
			{
				return new Kept();
			}
			return k;
		}

		/** The one goal kept before 11/19/2026, as a list of it (item 0 or none: empty). */
		static Kept fromOne(Integer item, Long got, String counts, Gson gson)
		{
			Kept k = new Kept();
			if (item == null || !k.add(item))
			{
				return k;
			}
			One g = k.find(item);
			g.got = got == null ? 0 : got;
			try
			{
				g.counts = g.got > 0 && counts != null ? gson.fromJson(counts, JsonObject.class) : null;
			}
			catch (RuntimeException ex)
			{
				g.counts = null;
			}
			return k;
		}
	}

	/** Whether the game's "New item added to your collection log" line is the goal's. */
	static boolean isIt(String added, String goalName)
	{
		return added != null && goalName != null && !goalName.isEmpty()
			&& added.trim().equalsIgnoreCase(goalName.trim());
	}

	/** What goes to the keep for one goal: the item, its model (null: none to send), and when it was got (0: not yet). */
	static JsonObject body(int id, String name, JsonObject model, long gotAt, JsonObject countsThen)
	{
		JsonObject o = new JsonObject();
		o.addProperty("id", id);
		o.addProperty("name", name == null ? "" : name.replaceAll("[\\x00-\\x1f\\x7f]", " ").trim());
		if (model != null)
		{
			o.add("model", model);
		}
		if (gotAt > 0)
		{
			JsonObject got = new JsonObject();
			got.addProperty("at", gotAt);
			if (countsThen != null)
			{
				got.add("counts", countsThen);
			}
			o.add("got", got);
		}
		return o;
	}

	/** The whole goal for the keep: the one shown (with its model) and the rest under it as "more" (none: no "more"). */
	static JsonObject body(JsonObject shown, List<JsonObject> more)
	{
		return body(shown, more, true);
	}

	/** As above; model false (the side tab's No 3D model): the first marked "nomodel", so the page builds it none. */
	static JsonObject body(JsonObject shown, List<JsonObject> more, boolean model)
	{
		if (!model)
		{
			shown.remove("model");
			shown.addProperty("nomodel", true);
		}
		if (more != null && !more.isEmpty())
		{
			JsonArray a = new JsonArray();
			for (JsonObject m : more)
			{
				a.add(m);
			}
			shown.add("more", a);
		}
		return shown;
	}
}

package wiki.outside;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What the plugin reads for the player's page beyond what's worn and carried, kept apart from RuneLite so it's tested
 * (docs/protocol.md, "Kept for the page"):
 * <ul>
 * <li>an item's charges, from the game's own chat line;</li>
 * <li>the bank, as the relay keeps it;</li>
 * <li>the deathbank (the Item Retrieval Service's), as the relay keeps it;</li>
 * <li>the character's model, as the page draws it;</li>
 * </ul>
 */
public final class Kept
{
	private Kept()
	{
	}

	// ---- charges (Jace: "show charges on the items that have charges like my tonalztics of ralos and archivist's
	// folio, if you can collect that info from the client"): the game says them only in its chat, when an item's
	// checked ("Your tonalztics of ralos has 1,234 charges left.") or as it's used, so they're read from there, as the
	// Hub's charge plugins read them

	/** "1,234 charges", "1 charge", "has 50 charges left", "(57 charges)", "uses remaining: 12" … */
	private static final Pattern CHARGES = Pattern.compile(
		"(?i)(?:\\b([0-9][0-9,]*)\\s+(?:charges?|uses?|scrolls?|doses?)\\b)|(?:(?:charges?|uses?)(?:\\s+(?:left|remaining))?\\s*[:]?\\s+([0-9][0-9,]*)\\b)");
	/** "none", "no charges left", "has run out" */
	private static final Pattern NONE = Pattern.compile("(?i)\\b(no charges|no more charges|has run out of charges|has no charges|is out of charges)\\b");

	/** The charges a game message tells of, or null: none told. 0 for "no charges". */
	public static Integer charges(String message)
	{
		if (message == null)
		{
			return null;
		}
		if (NONE.matcher(message).find())
		{
			return 0;
		}
		Matcher m = CHARGES.matcher(message);
		if (!m.find())
		{
			return null;
		}
		String n = (m.group(1) != null ? m.group(1) : m.group(2)).replace(",", "");
		try
		{
			long v = Long.parseLong(n);
			return v > Integer.MAX_VALUE ? null : (int) v;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** An item's name as the game says it in chat: lower case, without its "(charged)", "(e)", "(4)" or the like. */
	public static String spoken(String name)
	{
		return name == null ? "" : name.replaceAll("\\s*\\([^)]*\\)\\s*$", "").trim().toLowerCase(Locale.ROOT);
	}

	/** Whether a message is about this item (its spoken name in it), its name at least 5 letters so a short word ("ring") never does. */
	public static boolean about(String message, String name)
	{
		String n = spoken(name);
		return n.length() >= 5 && message != null && message.toLowerCase(Locale.ROOT).contains(n);
	}

