	/** 11/22/2026 (Jace at the Giant Mole, update 6's build: "recording started when i entered moles lair (non-instanced
	 *  location with option of instance, i entered non-instanced location) ... people spend hours here so probably not
	 *  ideal"): an open boss area starts with the fight with its boss; an instance and a raid on entering, as before. */
	@Test
	public void anOpenBossAreaStartsWithItsBossFight()
	{
		Presence.Area mole = Presence.area(6993, 0);
		assertEquals("Giant Mole", mole.name);
		// (the lair itself: nothing on entering; the Mole fought, by any case of its name; not a baby mole)
		assertTrue(Encounters.openArea(mole, false));
		assertFalse(Encounters.startsOnEntry(mole, false));
		assertTrue(Encounters.startsByFight(mole, false, "Giant Mole"));
		assertTrue(Encounters.startsByFight(mole, false, "giant mole"));
		assertTrue(Encounters.startsByFight(mole, false, "Giant\u00A0Mole"));
		assertFalse(Encounters.startsByFight(mole, false, "Baby Mole"));
		assertFalse(Encounters.startsByFight(mole, false, null));
		// (its instance: on entering, as before, and a fight there starts nothing more)
		assertFalse(Encounters.openArea(mole, true));
		assertTrue(Encounters.startsOnEntry(mole, true));
		assertFalse(Encounters.startsByFight(mole, true, "Giant Mole"));
		// (a raid: on entering, never by a fight)
		Presence.Area cox = null;
		for (Presence.Area a : Presence.AREAS)
		{
			if ("Chambers of Xeric".equals(a.name))
			{
				cox = a;
			}
		}
		assertEquals(Presence.RAID, cox.kind);
		assertFalse(Encounters.openArea(cox, false));
		assertTrue(Encounters.startsOnEntry(cox, false));
		assertTrue(Encounters.startsOnEntry(cox, true));
		assertFalse(Encounters.startsByFight(cox, false, "Great Olm"));
		assertFalse(Encounters.startsOnEntry(null, false));
		assertFalse(Encounters.startsByFight(null, false, "Giant Mole"));
		// (areas whose boss has another name: each king, not the area's name)
		Presence.Area dks = Presence.area(11588, 0);
		assertEquals("Dagannoth Kings", dks.name);
		assertTrue(Encounters.startsByFight(dks, false, "Dagannoth Rex"));
		assertTrue(Encounters.startsByFight(dks, false, "Dagannoth Supreme"));
		assertFalse(Encounters.startsByFight(dks, false, "Dagannoth Kings"));
		assertFalse(Encounters.startsByFight(dks, false, "Dagannoth"));
		// (and every name in BOSS_NPCS is one of Discord's boss areas)
		for (String named : Encounters.BOSS_NPCS.keySet())
		{
			boolean found = false;
			for (Presence.Area a : Presence.AREAS)
			{
				found |= a.name.equals(named) && Presence.BOSS.equals(a.kind);
			}
			assertTrue(named, found);
		}
	}

	/** 11/22/2026 (Jace: "it looks like the recording is not stopping after i kill the mole"; another player's hit came
	 *  first, so no kill credit and no count line): the boss they fought dead ends it once they're out of combat a few
	 *  ticks; and in an open area, a fight given up. */
	@Test
	public void theBossDeadWithNoCountLineEndsIt()
	{
		// (no death: never)
		assertFalse(Encounters.bossDown(1000, -1, 0));
		// (dead at 100, their last hit the killing one: BOSS_DOWN after, and QUIET after the last hit)
		assertFalse(Encounters.bossDown(100, 100, 100));
		assertFalse(Encounters.bossDown(100 + Encounters.QUIET - 1, 100, 100));
		assertTrue(Encounters.bossDown(100 + Math.max(Encounters.BOSS_DOWN, Encounters.QUIET), 100, 100));
		// (still fighting after it: another boss, a king's brother, hitting them)
		assertFalse(Encounters.bossDown(130, 100, 125));
		assertTrue(Encounters.bossDown(125 + Encounters.QUIET, 100, 125));
		// (a short wait: under ten seconds)
		assertTrue(Math.max(Encounters.BOSS_DOWN, Encounters.QUIET) + Encounters.DROP_WAIT <= 20);

		// (Jace's first kill walked through: the Mole fought from tick 0, hit every 4 ticks, dead at 60 with no line)
		int dead = 60, endedAt = -1;
		for (int t = 0; t < 200 && endedAt < 0; t++)
		{
			int last = Math.min(t - t % 4, dead);
			if (Encounters.bossDown(t, t >= dead ? dead : -1, last))
			{
				endedAt = t;
			}
		}
		assertEquals(dead + Encounters.QUIET, endedAt);

		// (a fight given up in an open area: the Mole dug in and chased 40 s isn't; 90 s with no hitsplat is)
		assertFalse(Encounters.fightStopped(67, 0));
		assertFalse(Encounters.fightStopped(Encounters.OPEN_IDLE - 1, 0));
		assertTrue(Encounters.fightStopped(Encounters.OPEN_IDLE, 0));
	}

	/** What goes to the page by itself (11/22/2026, Jace: only a fight with a result; leaving once fought is a failure) */
	@Test
	public void sendsByItselfOnlyWithAResult()
	{
		for (String r : new String[]{"killed", "completed", "looted", "claimed", "died", "failed", "stopped by hand"})
		{
			assertTrue(r, Encounters.sendsByItself(r, true, true));
			assertTrue(r, Encounters.sendsByItself(r, true, false));
		}
		assertTrue(Encounters.sendsByItself("left", true, true));
		assertFalse(Encounters.sendsByItself("left", true, false));
		for (String r : new String[]{"the fight stopped", "watched NPCs gone", "the time limit", "logged out or hopped",
			"client closed", "plugin turned off"})
		{
			assertFalse(r, Encounters.sendsByItself(r, true, true));
		}
		// (Record now: however it ended, but never from anywhere dangerous or a part split at the length limit)
		assertTrue(Encounters.sendsByItself("logged out or hopped", false, false));
		assertTrue(Encounters.sendsByItself("client closed", false, false));
		assertFalse(Encounters.sendsByItself("the Wilderness or PvP", false, true));
		assertFalse(Encounters.sendsByItself("the Wilderness or PvP", true, true));
		assertFalse(Encounters.sendsByItself(Encounters.SPLIT, false, true));
	}
}

package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalTest
{
	/** A goal's row dragged up or down (11/22/2026): the list reordered, the page's order following it under the one shown. */
	@Test
	public void movesAGoal()
	{
		Goal.Kept k = new Goal.Kept();
		k.add(1); k.add(2); k.add(3); k.add(4);
		assertTrue(k.move(4, 0));
		assertEquals(4, k.list.get(0).id);
		assertEquals(1, k.list.get(1).id);
		assertTrue(k.move(4, 9));
		assertEquals(4, k.list.get(3).id);
		assertFalse(k.move(4, 3));
		assertFalse(k.move(99, 0));
		assertTrue(k.move(3, 0));
		List<Integer> page = new ArrayList<>();
		for (Goal.One g : k.pageOrder())
		{
			page.add(g.id);
		}
		// (1 shown first, the rest in the list's order)
		assertEquals(java.util.Arrays.asList(1, 3, 2, 4), page);
	}

	@Test
	public void theLogLineNamesTheGoalWhateverItsCase()
	{
		assertTrue(Goal.isIt("Abyssal whip", "Abyssal whip"));
		assertTrue(Goal.isIt(" abyssal WHIP ", "Abyssal whip"));
		assertFalse(Goal.isIt("Abyssal dagger", "Abyssal whip"));
		assertFalse(Goal.isIt(null, "Abyssal whip"));
		assertFalse(Goal.isIt("Abyssal whip", ""));
	}

	@Test
	public void itsBodyHasTheItemAndWhenItWasGotOnlyOnceGot()
	{
		JsonObject b = Goal.body(4151, "Abyssal whip", null, 0, null);
		assertEquals(4151, b.get("id").getAsInt());
		assertEquals("Abyssal whip", b.get("name").getAsString());
		assertFalse(b.has("model"));
		assertFalse(b.has("got"));
		JsonObject counts = new JsonObject();
		counts.add("kills", new JsonObject());
		JsonObject got = Goal.body(4151, "Abyssal\nwhip", new JsonObject(), 1700000000000L, counts);
		assertEquals("Abyssal whip", got.get("name").getAsString());
		assertTrue(got.has("model"));
		assertEquals(1700000000000L, got.getAsJsonObject("got").get("at").getAsLong());
		assertTrue(got.getAsJsonObject("got").has("counts"));
	}

	// ---- the list (11/19/2026, Cranky: "add a goal item ... and you'd just have to x any you don't want anymore") ----

	@Test
	public void theFirstAddedIsShownTheRestFollowInTheirOrderEachOnce()
	{
		Goal.Kept k = new Goal.Kept();
		assertTrue(k.add(4151));
		assertTrue(k.add(11286));
		assertTrue(k.add(13576));
		assertFalse(k.add(11286));
		assertFalse(k.add(0));
		assertEquals(4151, k.shown);
		assertTrue(k.show(13576));
		assertFalse(k.show(13576));
		assertFalse(k.show(99999));
		List<Integer> order = new ArrayList<>();
		for (Goal.One g : k.pageOrder())
		{
			order.add(g.id);
		}
		assertEquals(List.of(13576, 4151, 11286), order);
	}

	@Test
	public void atMostTen()
	{
		Goal.Kept k = new Goal.Kept();
		for (int i = 1; i <= Goal.MOST; i++)
		{
			assertTrue(k.add(1000 + i));
		}
		assertFalse(k.add(5000));
		assertEquals(Goal.MOST, k.list.size());
	}

	@Test
	public void theOneShownTakenOffTheFirstLeftIsShown()
	{
		Goal.Kept k = new Goal.Kept();
		k.add(4151);
		k.add(11286);
		k.add(13576);
		k.show(11286);
		assertTrue(k.forget(11286));
		assertEquals(4151, k.shown);
		assertTrue(k.forget(13576));
		assertEquals(4151, k.shown);
		assertFalse(k.forget(13576));
		assertTrue(k.forget(4151));
		assertEquals(0, k.shown);
		assertTrue(k.list.isEmpty());
		assertTrue(k.add(11286));
		assertEquals(11286, k.shown);
	}

	@Test
	public void keptAndReadBackWithWhenEachWasGot()
	{
		Gson gson = new Gson();
		Goal.Kept k = new Goal.Kept();
		k.add(4151);
		k.add(11286);
		k.show(11286);
		JsonObject counts = new JsonObject();
		counts.add("kills", new JsonObject());
		k.find(4151).got = 1700000000000L;
		k.find(4151).counts = counts;
		Goal.Kept back = Goal.Kept.from(k.json(gson), gson);
		assertEquals(11286, back.shown);
		assertEquals(2, back.list.size());
		assertEquals(4151, back.list.get(0).id);
		assertEquals(1700000000000L, back.find(4151).got);
		assertTrue(back.find(4151).counts.has("kills"));
		assertEquals(0, back.find(11286).got);
		assertNull(back.find(11286).counts);
		// (anything broken reads as none; a shown that isn't in the list, the first)
		assertTrue(Goal.Kept.from("{nope", gson).list.isEmpty());
		assertTrue(Goal.Kept.from(null, gson).list.isEmpty());
		Goal.Kept odd = Goal.Kept.from("{\"shown\": 5, \"list\": [{\"id\": 4151}, {\"id\": 4151}, {\"x\": 1}, {\"id\": 13576}]}", gson);
		assertEquals(2, odd.list.size());
		assertEquals(4151, odd.shown);
	}

	@Test
	public void theOneGoalKeptBeforeIsTheListsFirst()
	{
		Gson gson = new Gson();
		Goal.Kept k = Goal.Kept.fromOne(4151, 1700000000000L, "{\"kills\": {\"Abyssal Sire\": 412}}", gson);
		assertEquals(1, k.list.size());
		assertEquals(4151, k.shown);
		assertEquals(1700000000000L, k.find(4151).got);
		assertEquals(412, k.find(4151).counts.getAsJsonObject("kills").get("Abyssal Sire").getAsInt());
		assertTrue(Goal.Kept.fromOne(null, null, null, gson).list.isEmpty());
		Goal.Kept notGot = Goal.Kept.fromOne(4151, null, null, gson);
		assertEquals(0, notGot.find(4151).got);
	}

	@Test
	public void theWholeGoalHasTheRestAsMoreOnlyWhenThereAreAny()
	{
		JsonObject top = Goal.body(4151, "Abyssal whip", new JsonObject(), 0, null);
		List<JsonObject> more = new ArrayList<>();
		assertFalse(Goal.body(top, more).has("more"));
		more.add(Goal.body(11286, "Draconic visage", null, 0, null));
		JsonObject whole = Goal.body(Goal.body(4151, "Abyssal whip", new JsonObject(), 0, null), more);
		assertEquals(1, whole.getAsJsonArray("more").size());
		assertFalse(whole.getAsJsonArray("more").get(0).getAsJsonObject().has("model"));
		assertTrue(whole.has("model"));
	}

	// (11/21/2026, round nine: the page builds a goal's model from the game's files when it comes without one, so No 3D
	// model is said, not left out)
	@Test
	public void noModelChosenTheFirstSaysSoAndOnlyIt()
	{
		List<JsonObject> more = new ArrayList<>();
		more.add(Goal.body(11286, "Draconic visage", null, 0, null));
		JsonObject none = Goal.body(Goal.body(4151, "Abyssal whip", null, 0, null), more, false);
		assertTrue(none.get("nomodel").getAsBoolean());
		assertFalse(none.has("model"));
		assertFalse(none.getAsJsonArray("more").get(0).getAsJsonObject().has("nomodel"));
		// (one shown as its model: no mark, as before)
		JsonObject shown = Goal.body(Goal.body(4151, "Abyssal whip", new JsonObject(), 0, null), new ArrayList<>(), true);
		assertFalse(shown.has("nomodel"));
		assertTrue(shown.has("model"));
		assertFalse(Goal.body(Goal.body(4151, "Abyssal whip", null, 0, null), null).has("nomodel"));
	}

	@Test
	public void noneTurningListsThemAllInTheirOrderAndPickingOneTurnsItAgain()
	{
		Gson gson = new Gson();
		Goal.Kept k = new Goal.Kept();
		k.add(4151);
		k.add(11286);
		k.show(11286);
		assertTrue(k.noModel());
		assertFalse(k.noModel());
		assertEquals(4151, k.pageOrder().get(0).id);
		Goal.Kept back = Goal.Kept.from(k.json(gson), gson);
		assertFalse(back.model);
		assertEquals(11286, back.shown);
		assertTrue(back.show(11286));
		assertTrue(back.model);
		assertEquals(11286, back.pageOrder().get(0).id);
		// (kept before this, with no "model": one turns)
		assertTrue(Goal.Kept.from("{\"shown\": 4151, \"list\": [{\"id\": 4151}]}", gson).model);
	}
}

package wiki.outside;

import com.google.gson.JsonObject;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Charges from the game's chat, the bank and the model as the relay keeps them (Kept, 11/14/2026). */
public class KeptTest
{
	@Test
	public void chargesAsTheGameSaysThem()
	{
		assertEquals(Integer.valueOf(1234), Kept.charges("Your tonalztics of ralos has 1,234 charges left."));
		assertEquals(Integer.valueOf(1), Kept.charges("Your ring of recoil has 1 charge left."));
		assertEquals(Integer.valueOf(57), Kept.charges("Your archivist's folio has 57 charges remaining."));
		assertEquals(Integer.valueOf(12), Kept.charges("Uses remaining: 12"));
		assertEquals(Integer.valueOf(0), Kept.charges("Your blowpipe has run out of charges."));
		assertNull(Kept.charges("You eat the shark."));
		assertNull(Kept.charges(null));
	}

	@Test
	public void anItemByTheNameTheGameSays()
	{
		assertEquals("tonalztics of ralos", Kept.spoken("Tonalztics of ralos (charged)"));
		assertTrue(Kept.about("Your tonalztics of ralos has 50 charges.", "Tonalztics of ralos (charged)"));
		assertFalse(Kept.about("Your ring has 5 charges.", "Ring (i)"));   // (too short a name to tell by)
		assertFalse(Kept.about("Your blowpipe has 5 charges.", "Shark"));
	}

	@Test
	public void theBankItsTabsAndNames()
	{
		Map<Integer, Object[]> names = new LinkedHashMap<>();
		names.put(995, new Object[]{"Coins", 1L});
		JsonObject b = Kept.bank(new int[]{995, -1, 4151}, new int[]{1000, 0, 0}, new int[]{2, 0, 0, 0, 0, 0, 0, 0, 0}, names);
		assertEquals("[[995,1000],[4151,0]]", b.get("items").toString());   // (a placeholder: none of it)
		assertEquals("[2,0,0,0,0,0,0,0,0]", b.get("tabs").toString());
		assertEquals("{\"995\":[\"Coins\",1]}", b.get("names").toString());
	}

	@Test
	public void theDeathbankWhereAndWhetherLocked()
	{
		assertEquals("Hespori", Kept.deathbankWhere(15)[0]);
		assertEquals(true, Kept.deathbankWhere(15)[1]);
		assertEquals(false, Kept.deathbankWhere(16)[1]);
		// (Zulrah's unlocked value is 0; -1 is no deathbank's window)
		assertEquals("Zulrah", Kept.deathbankWhere(0)[0]);
		assertNull(Kept.deathbankWhere(-1));
		assertEquals("Unknown", Kept.deathbankWhere(999)[0]);
	}

	@Test
	public void theDeathbankItsItemsAndEmptiedNone()
	{
		Map<Integer, Object[]> names = new LinkedHashMap<>();
		names.put(4151, new Object[]{"Abyssal whip", 1_500_000L});
		JsonObject d = Kept.deathbank("Hespori", true, new int[]{4151, -1, 995}, new int[]{1, 0, 25000}, names);
		assertEquals("{\"where\":\"Hespori\",\"locked\":true,\"items\":[[4151,1],[995,25000]],\"names\":{\"4151\":[\"Abyssal whip\",1500000]}}", d.toString());
		assertNull(Kept.deathbank("Hespori", false, new int[]{-1, -1}, new int[]{0, 0}, names));
	}

	@Test
	public void theDeathbankAtADeathByTheGamesLineOrTheRegion()
	{
		assertEquals("Hespori", Kept.deathbankAt("You have items stored in an item retrieval service. Speak to Arno at the Farming Guild.", -1));
		assertEquals("Phosani's Nightmare", Kept.deathbankAt("... Sister Senga ...", 15515));
		assertEquals("Grotesque Guardians", Kept.deathbankAt(Kept.DEATHBANK_LINE + ".", 6727));
		assertEquals("Unknown", Kept.deathbankAt(Kept.DEATHBANK_LINE + ".", 12850));
	}

	@Test
	public void whatADeathTookLessWhatWasKept()
	{
		// (a whip, a defender and a fire cape kept; the sharks, the coins and a second ring went)
		int[][] lost = Kept.lost(
			new int[]{4151, 385, 385, 995, 12954, 6570, 2550, 2550, -1},
			new int[]{1, 1, 1, 30000, 1, 1, 1, 1, 0},
			new int[]{4151, 12954, 6570, 2550, -1},
			new int[]{1, 1, 1, 1, 0});
		assertEquals("[385, 995, 2550]", java.util.Arrays.toString(lost[0]));
		assertEquals("[2, 30000, 1]", java.util.Arrays.toString(lost[1]));
		JsonObject d = Kept.deathbank("Hespori", true, lost[0], lost[1], new LinkedHashMap<>(), true);
		assertEquals("death", d.get("from").getAsString());
		assertFalse(Kept.deathbank("Hespori", true, lost[0], lost[1], new LinkedHashMap<>()).has("from"));
	}

	@Test
	public void theModelLeavesOutWhatTheGameNeverDraws()
	{
		float[] x = {0, 10.4f, 0, 9000}, y = {0, 0, -10, 0}, z = {0, 0, 0, 0};
		int[] a = {0, 0, 1}, b = {1, 1, 2}, c = {2, 2, 3};
		int[] c1 = {100, 200, 300}, c3 = {-1, Kept.HIDDEN, 5};
		short[] tex = {-1, -1, 7};
		JsonObject m = Kept.model(x, y, z, 4, a, b, c, 3, c1, c3, null, new byte[]{0, 0, 0}, tex);
		assertEquals("[0,0,0,10,0,0,0,-10,0,8192,0,0]", m.get("v").toString());   // (rounded, kept in range)
		assertEquals("[0,1,2,1,2,3]", m.get("f").toString());                     // (the hidden face left out)
		assertEquals("[100,-1]", m.get("c").toString());                           // (textured: -1)
	}

	@Test
	public void theModelAsTheGameLitItWithItsTextures()
	{
		float[] x = {0, 128, 0}, y = {0, 0, 128}, z = {0, 0, 0};
		int[] a = {0, 0}, b = {1, 1}, c = {2, 2};
		int[] c1 = {100, 50}, c2 = {200, 60}, c3 = {Kept.FLAT, 70};
		short[] tex = {-1, 7};
		JsonObject m = Kept.model(x, y, z, 3, a, b, c, 2, c1, c2, c3, null, new byte[]{0, 127}, tex,
			new byte[]{0, 2}, new byte[]{0, 0}, new int[]{0}, new int[]{1}, new int[]{2});
		assertEquals("[100,100,100,50,60,70]", m.get("g").toString());   // (flat: one colour; textured: lightnesses)
		assertEquals("[255,128]", m.get("a").toString());
		assertEquals("[0,2]", m.get("p").toString());
		assertEquals("[-1,7]", m.get("t").toString());
		assertEquals("[0,0,0,0,0,0,0,0,4096,0,0,4096]", m.get("uv").toString());   // (the texture triangle is the face)
	}

	@Test
	public void aMotionsFramesAsLittleEndianNumbers()
	{
		String f = Kept.frame(new float[]{1, -2}, new float[]{3, 9000}, new float[]{0, 256}, 2);
		byte[] b = java.util.Base64.getDecoder().decode(f);
		assertEquals(12, b.length);
		java.nio.ByteBuffer bb = java.nio.ByteBuffer.wrap(b).order(java.nio.ByteOrder.LITTLE_ENDIAN);
		assertEquals(1, bb.getShort());
		assertEquals(3, bb.getShort());
		assertEquals(0, bb.getShort());
		assertEquals(-2, bb.getShort());
		assertEquals(8192, bb.getShort());   // (kept in range)
		assertEquals(256, bb.getShort());
		JsonObject o = Kept.frames(java.util.Arrays.asList(f, f), 12.5);
		assertEquals("{\"fps\":12.5,\"v\":[\"" + f + "\",\"" + f + "\"]}", o.toString());
	}

	@Test
	public void aMotionsNameFromTheCommand()
	{
		assertEquals("dance 2", OutsidePlugin.motionName(new String[]{"Dance", "2"}));
		assertNull(OutsidePlugin.motionName(new String[]{}));
		assertNull(OutsidePlugin.motionName(new String[]{"no!"}));
		assertNull(OutsidePlugin.motionName(new String[]{"aaaaaaaaaaaaaaaaaaaaaaaaa"}));
	}

	// (11/15/2026: effects and the ground)
	@Test
	public void theEffectsMergedAfterThePlayersOwnAreFound()
	{
		// the player's 3 vertices, then a 2-vertex effect merged after them
		float[] x = {0, 1, 2, 10, 11}, z = {0, 0, 0, 5, 6};
		java.util.List<float[]> ex = java.util.Arrays.asList(new float[]{10, 11}), ez = java.util.Arrays.asList(new float[]{5, 6});
		assertEquals(3, Kept.ownVertices(x, z, 5, ex, ez, new int[]{2}));
		// not where the effect is: all the player's
		assertEquals(5, Kept.ownVertices(x, z, 5, ex, java.util.Arrays.asList(new float[]{5, 7}), new int[]{2}));
		// not merged at all (the model's no bigger than the effect): all the player's
		assertEquals(2, Kept.ownVertices(new float[]{10, 11}, new float[]{5, 6}, 2, ex, ez, new int[]{2}));
		assertEquals(5, Kept.ownVertices(x, z, 5, java.util.Collections.emptyList(), java.util.Collections.emptyList(), new int[]{}));
	}

	@Test
	public void aModelTrimmedToThePlayersOwn()
	{
		JsonObject m = Kept.model(new float[]{0, 1, 0, 9, 9, 9}, new float[]{0, 0, 1, 0, 0, 0}, new float[]{0, 0, 0, 0, 1, 2}, 6,
			new int[]{0, 3}, new int[]{1, 4}, new int[]{2, 5}, 2, new int[]{100, 200}, null, new int[]{-1, -1}, null, null, null, null, null, null, null, null);
		JsonObject t = Kept.trim(m, 3);
		assertEquals("[0,0,0,1,0,0,0,1,0]", t.get("v").toString());
		assertEquals("[0,1,2]", t.get("f").toString());
		assertEquals("[100]", t.get("c").toString());
		assertEquals("[100,100,100]", t.get("g").toString());
		assertEquals(m, Kept.trim(m, 6));   // (nothing past it: as it was)
	}

	@Test
	public void theGroundAsAModel()
	{
		int[] plain = {0, 0, 0, 128, 0, 0, 0, -10, 128, 100, 101, 102, -1, 0, 0, 4096, 0, 0, 4096};
		int[] hidden = plain.clone();
		hidden[10] = Kept.TILE_HIDDEN;
		int[] textured = plain.clone();
		textured[12] = 5;
		textured[9] = 0x1234 | 70;
		JsonObject g = Kept.ground(java.util.Arrays.asList(plain, hidden, textured));
		assertEquals("[0,1,2,3,4,5]", g.get("f").toString());
		assertEquals("[100,-1]", g.get("c").toString());
		assertEquals(6 * 3, g.getAsJsonArray("v").size());
		assertEquals((0x1234 | 70) & 127, g.getAsJsonArray("g").get(3).getAsInt());   // (a textured corner: its lightness)
		assertEquals("[-1,5]", g.get("t").toString());
		assertEquals("[0,0,0,0,0,0,0,0,4096,0,0,4096]", g.get("uv").toString());
	}
}

