package wiki.outside;

import com.google.gson.JsonObject;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** What they're doing, as RuneLite's Discord plugin shows it (11/16/2026; Presence). */
public class PresenceTest
{
	/** the relays' own checks of a presence (game.ts's AREA_NAME, PRESENCE_KINDS, PRESENCE_GRID) */
	private static final Pattern AREA_NAME = Pattern.compile("[A-Za-z0-9][A-Za-z0-9 '.()&-]{0,47}");
	private static final Set<String> KINDS = new HashSet<>(java.util.Arrays.asList("boss", "city", "dungeon", "minigame", "raid", "region"));

	@Test
	public void discordsAreasEachWithAPointTheRelaysTake()
	{
		assertEquals(398, Presence.AREAS.length);
		int placed = 0;
		for (Presence.Area a : Presence.AREAS)
		{
			assertTrue(a.name, AREA_NAME.matcher(a.name).matches());
			assertTrue(a.name, KINDS.contains(a.kind));
			if (a.at == null)
			{
				continue;
			}
			placed++;
			boolean zanaris = a.at[0] == 2368 && a.at[1] == 4416;
			assertTrue(a.name, zanaris || (a.at[0] % 32 == 0 && a.at[1] % 32 == 0 && a.at[0] >= 960 && a.at[0] < 4096
				&& a.at[1] >= 2048 && a.at[1] < 4224));
		}
		assertTrue(placed > 300);
	}

	@Test
	public void areasByTheirRegionsAndWhereTheGlobeStandsThem()
	{
		Presence.Area wc = Presence.area(6198, 0);
		assertEquals("Woodcutting Guild", wc.name);
		assertEquals("region", wc.kind);
		assertNotNull(wc.at);
		assertEquals("Zulrah", Presence.area(9007, 0).name);
		assertArrayEquals(new int[]{2368, 4416}, Presence.area(9541, 0).at);              // (Zanaris, on the moon)
		assertArrayEquals(new int[]{1216, 3520}, Presence.area(12889, 0).at);             // (the Chambers: Mount Quidamortem)
		assertArrayEquals(new int[]{2880, 3776}, Presence.area(11347, 0).at);             // (General Graardor: Trollheim)
		assertEquals("Lumbridge", Presence.area(12850, 0).name);
		assertArrayEquals(new int[]{3232, 3232}, Presence.area(12850, 0).at);             // (its one region's middle)
		// (an underground area as the place above it: Edgeville Dungeon's regions under Edgeville)
		int[] edge = Presence.area(12441, 0).at;
		assertTrue(edge[1] < 4224 && edge[0] >= 3008 && edge[0] < 3200);
		// (Nightmare Zone's region, on its ground floor, is the King Black Dragon's lair: no area, as Discord has it)
		assertNull(Presence.area(9033, 0));
		assertEquals("Nightmare Zone", Presence.area(9033, 1).name);
		assertNull(Presence.area(14000, 0));                                             // (not on Discord's list: "In Game")
	}

	@Test
	public void aKnownWayInWinsOverThePlaceAboveIt()
	{
		// (11/16/2026: the Guardians of the Rift stood in the Murkshore Sea, the place above its temple)
		assertArrayEquals(new int[]{3104, 3168}, Presence.place(Presence.area(14484, 0)));
		assertArrayEquals(new int[]{3232, 3104}, Presence.place(Presence.BY_REGION.values().stream().filter(a -> a.name.equals("Kalphite Queen")).findFirst().get()));
		assertArrayEquals(new int[]{3424, 3488}, Presence.place(Presence.BY_REGION.values().stream().filter(a -> a.name.equals("Temple Trekking")).findFirst().get()));
	}

	@Test
	public void theSkillComesFromTheirOwnExperienceAndANewSceneClearsIt()
	{
		Presence p = new Presence();
		p.scene(6198, 0);
		p.experience("Woodcutting", 1000, 0);                 // (the first reading only remembered)
		assertTrue(p.now(0, false).get("skill").isJsonNull());
		p.experience("Woodcutting", 1050, 1000);
		JsonObject o = p.now(2000, false);
		assertEquals("Woodcutting", o.get("skill").getAsString());
		assertEquals("Woodcutting Guild", o.get("area").getAsString());
		p.experience("Hitpoints", 100, 0);
		p.experience("Hitpoints", 200, 3000);                // (never Hitpoints: Discord's never names it)
		assertEquals("Woodcutting", p.now(4000, false).get("skill").getAsString());
		p.experience("Slayer", 10, 0);
		p.experience("Slayer", 20, 1500);
		p.experience("Woodcutting", 1100, 5000);
		assertEquals("Slayer", p.now(6000, false).get("skill").getAsString());   // (Slayer and Fishing first)
		assertEquals("Woodcutting", p.now(1500 + Presence.SKILL_MS + 1, false).get("skill").getAsString());
		assertTrue(p.now(5000 + Presence.SKILL_MS + 1, false).get("skill").isJsonNull());   // (5 minutes with none)
		p.scene(12850, 0);                                    // (a new scene: the skill goes till the next drop)
		assertTrue(p.now(7000, false).get("skill").isJsonNull());
	}

	@Test
	public void somewhereDangerousSaysNothing()
	{
		Presence p = new Presence();
		p.scene(6198, 0);
		p.experience("Woodcutting", 1000, 0);
		p.experience("Woodcutting", 1050, 1000);
		JsonObject o = p.now(2000, true);
		assertTrue(o.get("skill").isJsonNull() && o.get("area").isJsonNull() && o.get("kind").isJsonNull());
		assertFalse(o.has("x"));
	}

	@Test
	public void itGoesAsItChangesOnceAMinuteAtMostAndClearsAtOnce()
	{
		Presence p = new Presence();
		p.scene(6198, 0);
		JsonObject first = p.due(0, false);
		assertEquals("Woodcutting Guild", first.get("area").getAsString());
		p.took(first, 0);
		assertNull(p.due(1000, false));                       // (nothing changed)
		p.scene(12850, 0);
		assertNull(p.due(30_000, false));                     // (changed, but within the minute)
		JsonObject later = p.due(60_000, false);              // (the latest, once it's up)
		assertEquals(p.now(60_000, false), later);
		p.took(later, 60_000);
		JsonObject clear = p.due(61_000, true);               // (somewhere dangerous: at once)
		assertTrue(clear.get("area").isJsonNull());
		p.took(clear, 61_000);
		assertNull(p.due(62_000, true));
		p.loggedOut();
		assertTrue(p.now(63_000, false).get("area").isJsonNull());
	}
}

package wiki.outside;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Quests, diaries, combat achievements and the slayer task (11/15/2026): the shapes docs/protocol.md gives them. */
public class ProgressTest
{
	@Test
	public void karamjaCountsAtTwo()
	{
		// (Karamja's first three: 0 not started, 1 started, 2 its tasks done; Dink's isComplete)
		assertFalse(Progress.diaryDone(VarbitID.ATJUN_EASY_DONE, 1));
		assertTrue(Progress.diaryDone(VarbitID.ATJUN_EASY_DONE, 2));
		assertFalse(Progress.diaryDone(VarbitID.ATJUN_HARD_DONE, 1));
		assertTrue(Progress.diaryDone(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE, 1));
		assertTrue(Progress.diaryDone(VarbitID.VARROCK_DIARY_EASY_COMPLETE, 1));
		assertFalse(Progress.diaryDone(VarbitID.VARROCK_DIARY_EASY_COMPLETE, 0));
	}

	@Test
	public void anArea()
	{
		JsonArray a = Progress.area(Progress.DIARY[5], new int[]{2, 1, 0, 0}, 23, 81);
		assertEquals("[1,0,0,0,23,81]", a.toString());
		assertEquals(12, Progress.AREAS.length);
		assertEquals(12, Progress.DIARY.length);
		assertEquals(12, Progress.AREA_IDS.length);
		assertEquals("Karamja", Progress.AREAS[5]);
	}

	@Test
	public void combat()
	{
		JsonObject c = Progress.combat(1234, new int[]{33, 41, 30, 12, 2, 0}, new int[]{33, 115, 304, 820, 1465, 2005});
		assertEquals(1234, c.get("points").getAsInt());
		assertEquals(6, c.getAsJsonArray("tiers").size());
		assertEquals("[33,33]", c.getAsJsonArray("tiers").get(0).toString());
		assertEquals("[0,2005]", c.getAsJsonArray("tiers").get(5).toString());
	}

	@Test
	public void quests()
	{
		JsonObject q = Progress.quests(201, 216, Arrays.asList("Cook's Assistant", "Dragon Slayer I"), Collections.singletonList("  Desert   Treasure II "), Collections.singletonList("Sins of the Father"));
		assertEquals(201, q.get("points").getAsInt());
		assertEquals(216, q.get("total").getAsInt());
		assertEquals(2, q.getAsJsonArray("done").size());
		assertEquals("Desert Treasure II", q.getAsJsonArray("started").get(0).getAsString());
		assertEquals("Sins of the Father", q.getAsJsonArray("todo").get(0).getAsString());
	}

	@Test
	public void slayer()
	{
		JsonObject s = Progress.slayer("Abyssal demons", 87, 180, "Catacombs of Kourend", 1450, 312);
		assertEquals("Abyssal demons", s.get("task").getAsString());
		assertEquals(87, s.get("left").getAsInt());
		assertEquals(180, s.get("of").getAsInt());
		assertEquals("Catacombs of Kourend", s.get("area").getAsString());
		// (no task: the points and the streak still go)
		JsonObject none = Progress.slayer(null, 0, 0, null, 1450, 312);
		assertTrue(none.get("task").isJsonNull());
		assertTrue(none.get("area").isJsonNull());
		assertEquals(0, none.get("left").getAsInt());
		assertEquals(312, none.get("streak").getAsInt());
		// (a task whose amount given reads under what's left: never "87 of 50")
		assertEquals(87, Progress.slayer("Hellhounds", 87, 50, null, 0, 0).get("of").getAsInt());
	}

	@Test
	public void questsGroupedAsTheGameHasThem()
	{
		// (11/16/2026: free, members and miniquests, and each one's points, from the game's quest table)
		JsonObject q = Progress.quests(3, Arrays.asList(
			new Progress.Q("Cook's Assistant", 2, false, false, 1),
			new Progress.Q("The Corsair Curse", 1, false, false, 2),
			new Progress.Q("Dragon Slayer II", 0, true, false, 5),
			new Progress.Q("Bear Your Soul", 1, true, true, 0)));
		assertEquals(4, q.get("total").getAsInt());
		assertEquals("[\"Cook's Assistant\"]", q.getAsJsonArray("done").toString());
		assertEquals("[\"Dragon Slayer II\"]", q.getAsJsonArray("started").toString());
		assertEquals("[\"The Corsair Curse\",\"Bear Your Soul\"]", q.getAsJsonArray("todo").toString());
		assertEquals("[\"Cook's Assistant\",\"The Corsair Curse\"]", q.getAsJsonArray("free").toString());
		assertEquals("[\"Bear Your Soul\"]", q.getAsJsonArray("mini").toString());
		assertEquals(5, q.getAsJsonObject("qp").get("Dragon Slayer II").getAsInt());
		assertTrue(!q.getAsJsonObject("qp").has("Bear Your Soul"));
	}

	@Test
	public void aQuestOfSubquestsHasTheirPoints()
	{
		assertEquals(2, Progress.ownOrParts(2, 10));
		assertEquals(10, Progress.ownOrParts(0, 10));
		assertEquals(0, Progress.ownOrParts(0, null));
	}
}

package wiki.outside;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** The runs (11/21/2026, round six; ghillie's claude/outstation.md, "Encounters, round six"): the Gauntlet, the Corrupted
 *  Gauntlet and the Fortis Colosseum each one recording, started by entering its instance and ended as the game ends
 *  it. The game's side (the click, the map, the chest's inventory) in the local world: tools/local-world's ::testgauntlet
 *  and ::testcolosseum. */
public class RunsTest
{
	@Test
	public void eachRunIsItsInstanceOnly()
	{
		// (RuneLite's Screenshot plugin's GAUNTLET_REGION and CORRUPTED_GAUNTLET_REGION; Discord's Fortis Colosseum)
		assertSame(Encounters.GAUNTLET, Encounters.runAt(7512, true));
		assertSame(Encounters.CORRUPTED, Encounters.runAt(7768, true));
		assertSame(Encounters.COLOSSEUM, Encounters.runAt(7216, true));
		// (7216 not an instance is the city's ground outside the Colosseum; the lobbies are no run)
		assertNull(Encounters.runAt(7216, false));
		assertNull(Encounters.runAt(7316, true));
		assertNull(Encounters.runAt(12127, false));
		assertNull(Encounters.runAt(12850, true));
		assertEquals("The Gauntlet", Encounters.GAUNTLET.name);
		assertEquals("The Corrupted Gauntlet", Encounters.CORRUPTED.name);
		assertEquals("Fortis Colosseum", Encounters.COLOSSEUM.name);
	}

	@Test
	public void theWayInIsItsObjectAndOption()
	{
		// (revision 242's cache: 37340 shows as 36083 "Enter" or 36084 "Enter", "Enter-corrupted"; the arena's 50751)
		assertSame(Encounters.GAUNTLET, Encounters.runEntered(37340, "Enter"));
		assertSame(Encounters.CORRUPTED, Encounters.runEntered(37340, "Enter-corrupted"));
		assertSame(Encounters.CORRUPTED, Encounters.runEntered(36084, "Enter-corrupted"));
		assertSame(Encounters.COLOSSEUM, Encounters.runEntered(50751, "Enter"));
		assertNull(Encounters.runEntered(37340, "Examine"));
		// (the Colosseum's entrance from the city goes to the lobby, not the arena; the Gauntlet Portal to its lobby)
		assertNull(Encounters.runEntered(50749, "Enter"));
		assertNull(Encounters.runEntered(36081, "Enter"));
		assertTrue(Encounters.GAUNTLET_CHESTS.contains(37341));
		assertTrue(Encounters.GAUNTLET_CHESTS.contains(36087));
	}

	@Test
	public void theCountLinesAreReadWithTheGamesColourMacros()
	{
		assertTrue(Encounters.KILL_LINE.matcher("Your Gauntlet completion count is: 12.").matches());
		assertTrue(Encounters.KILL_LINE.matcher("Your Corrupted Gauntlet completion count is: 3.").matches());
		assertTrue(Encounters.KILL_LINE.matcher("Your Sol Heredit kill count is: 1.").matches());
		java.util.regex.Matcher m = Encounters.KILL_LINE.matcher("Your Vorkath kill count is: @mes_hl_red@1,418.");
		assertTrue(m.matches());
		assertEquals("Vorkath", m.group(1));
		assertEquals("1,418", m.group(2));
		// (a Colosseum wave's line is no count line: it never ends the run)
		assertTrue(!Encounters.KILL_LINE.matcher("Wave 3 completed! Wave duration: 0:42.60").matches());
	}

	private static String ends(Encounters.Run run, boolean in, boolean lobby, int out, int kill, int now, boolean looted,
		int endAt, String endWhy)
	{
		return Encounters.runEnding(run, in, lobby, out, kill, now, looted, endAt, endWhy);
	}

	@Test
	public void aGauntletEndsAtItsChestOrLeaving()
	{
		Encounters.Run g = Encounters.GAUNTLET;
		// (preparing: in the instance, nothing ends it)
		assertNull(ends(g, true, false, 0, -1, 900, false, -1, null));
		// (the platform or an escape before the kill: left, a few ticks out)
		assertNull(ends(g, false, true, Encounters.RUN_LEFT, -1, 900, false, -1, null));
		assertEquals("left", ends(g, false, true, Encounters.RUN_LEFT + 1, -1, 900, false, -1, null));
		// (the Hunllef killed: sent to the lobby, it waits for the chest)
		assertNull(ends(g, false, true, 40, 1000, 1040, false, -1, null));
		assertNull(ends(g, false, true, 400, 1000, 1400, false, -1, null));
		// (the chest's loot is loot()'s ending: the rule waits it out)
		assertNull(ends(g, false, true, 12, 1000, 1012, true, 1018, "looted"));
		// (killed, and the lobby left unlooted, or a long wait: completed)
		assertEquals("completed", ends(g, false, false, 200, 1000, 1200, false, -1, null));
		assertEquals("completed", ends(g, false, true, 500, 1000, 1000 + Encounters.RUN_CHEST_WAIT, false, -1, null));
		// (a death is onActorDeath's: an ending already due)
		assertNull(ends(g, false, true, 8, -1, 900, false, 906, "died"));
	}

	@Test
	public void aColosseumEndsOnLeavingTheArena()
	{
		Encounters.Run c = Encounters.COLOSSEUM;
		// (every wave, and Sol Heredit's count: nothing ends it)
		assertNull(ends(c, true, false, 0, 3000, 3005, false, -1, null));
		// (claimed, still in the arena: it goes on, however long; Jace, 11/21/2026: "it should end when you leave the arena")
		assertNull(ends(c, true, false, 0, 3000, 3400, true, -1, null));
		// (claimed and out of the arena: ended, "claimed")
		assertEquals("claimed", ends(c, false, false, Encounters.RUN_LEFT + 1, 3000, 3420, true, -1, null));
		// (out of the arena with nothing claimed: left; a death's ending isn't cut short)
		assertEquals("left", ends(c, false, false, Encounters.RUN_LEFT + 1, -1, 500, false, -1, null));
		assertNull(ends(c, false, false, Encounters.RUN_LEFT + 1, -1, 500, false, 506, "died"));
		assertEquals("the time limit", ends(c, true, false, 0, -1, Encounters.RAID_MOST, false, -1, null));
	}
}

package wiki.outside;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.eventbus.Subscribe;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** RuneLite's event bus won't start a plugin whose listener isn't named "on" and its event's name (11/19/2026: update 4
 *  went to the Hub with goalOnNpcLoot and wouldn't switch on). Every @Subscribe here, as the event bus checks it. */
public class SubscribeTest
{
	@Test
	public void listenersAreNamedAsTheEventBusRequires()
	{
		Set<String> seen = new HashSet<>();
		int n = 0;
		for (Method m : OutsidePlugin.class.getDeclaredMethods())
		{
			if (m.getAnnotation(Subscribe.class) == null)
			{
				continue;
			}
			n++;
			assertEquals(m + ": one parameter, the event", 1, m.getParameterCount());
			assertEquals(m + ": named for its event", "on" + m.getParameterTypes()[0].getSimpleName(), m.getName());
			assertTrue(m + ": one listener an event", seen.add(m.getName()));
		}
		assertTrue("the plugin listens to something", n > 0);
	}

	/** The encounters' recorder is on the event bus too (11/21/2026): the same rule for its listeners. */
	@Test
	public void theRecordersListenersToo()
	{
		Set<String> seen = new HashSet<>();
		int n = 0;
		for (Method m : Encounters.class.getDeclaredMethods())
		{
			if (m.getAnnotation(Subscribe.class) == null)
			{
				continue;
			}
			n++;
			assertEquals(m + ": one parameter, the event", 1, m.getParameterCount());
			assertEquals(m + ": named for its event", "on" + m.getParameterTypes()[0].getSimpleName(), m.getName());
			assertTrue(m + ": one listener an event", seen.add(m.getName()));
		}
		assertTrue("the recorder listens to something", n > 0);
	}
}

package wiki.outside;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.security.SecureRandom;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TendTest
{
	@Test
	public void aTokenIsWhatTheRelaysTake()
	{
		SecureRandom r = new SecureRandom();
		String t = Tend.token(r);
		assertTrue(t, t.matches("^[A-Za-z0-9_-]{43}$"));
		assertNotEquals(t, Tend.token(r));
	}

	@Test
	public void theBodyCarriesTheToken()
	{
		Gson gson = new Gson();
		JsonObject o = gson.fromJson(Tend.body("abc", gson), JsonObject.class);
		assertEquals("abc", o.get("token").getAsString());
		assertEquals(1, o.size());
	}
}
